('creature.norse.sleipnir','EIGHT_LEGGED_HORSE','{}','["carries his rider over the bridge to Hel and across Hel''s gate"]','[]',NULL,'Odin''s horse.',NULL),
('creature.mesopotamian.bull_of_heaven','DIVINE_BULL','{}','["its snorting opens pits that swallow hundreds of men"]','[]',NULL,'Given by Anu at Ishtar''s demand.','Killed by Gilgamesh and Enkidu.'),
('demon.hindu.ravana','RAKSHASA_KING','{"heads": 10}','["boon of Brahmā against gods and demons", "flying chariot Puṣpaka"]','[]','Laṅkā','Rākṣasa king who won his boon by austerities.','Slain by Rāma with the weapon of Brahmā.');

