INSERT OR IGNORE INTO myth_event_profiles(
    entity_id,event_type,time_layer,cause_summary,process_summary,result_summary,symbolism_summary
) VALUES
('event.chinese.havoc_in_heaven','NOVEL_EPISODE','Ming novel (later literary reception)','Sun Wukong seeks immortality and will not accept a lowly place in heaven.','He learns transformations, takes the iron staff, erases names from the register of death, eats the peaches and elixir and defeats heaven''s armies.','Erlang captures him, the furnace fails to destroy him, and Rulai pins him under the Mountain of Five Elements.','A literary episode; kept in the later-reception layer.'),
('event.chinese.nezha_sea_uproar','NOVEL_EPISODE','Ming novel (later literary reception)','The child Nezha stirs the sea with his sash and kills the dragon king''s men and son.','The dragon kings seize his parents; Nezha returns his flesh and bones to them; his teacher rebuilds him from lotus.','Reborn, Nezha pursues his father until Li Jing receives the golden pagoda.','A novel episode; later stage and film versions are not merged.'),
('event.greek.theogony_succession','COSMOGONY_AND_SUCCESSION','Archaic Greek poetry (c. 700 BCE)','Each ruler of the gods fears being overthrown by a child.','Ouranos is castrated by Cronus; Cronus swallows his children; Zeus, saved by a stone, wins the war against the Titans and Typhoeus.','The gods ask Zeus to reign, and he divides their honours.','One poet''s ordering of the gods; other Greek genealogies differ.'),
('event.norse.thor_utgard','QUEST_AND_CONTESTS','Snorri''s Edda (c. 1220)','Thor sets out east to Jötunheimr with Loki.','A giant''s glove, an unopenable bag, and contests in eating, racing, drinking, lifting and wrestling.','Útgarða-Loki reveals that every contest was an illusion and vanishes.','Thor''s opponents were fire, thought, the sea, the Midgard Serpent and old age.'),
('event.babylonian.gilgamesh_epic','EPIC_CYCLE','Standard Babylonian recension','Gilgamesh oppresses Uruk; the gods make Enkidu as his match.','Friendship, the Cedar Forest, Ishtar and the Bull of Heaven, Enkidu''s death, the search for Uta-napishti.','Gilgamesh loses the plant of rejuvenation and returns to the walls of Uruk.','Tablet XII, a translation of a Sumerian poem, is treated as an appendix and not retold here.'),
('event.japanese.ame_no_iwato','COSMIC_CRISIS','Age of the Gods (Kojiki, Upper Scroll)','Susanoo''s ravages and the death of the heavenly weaving maiden.','Amaterasu hides; the world falls into darkness; the deities hold an assembly, make a mirror and jewels and stage Ame-no-Uzume''s dance.','Amaterasu is drawn out, light returns and Susanoo is expelled.','Often read as a myth of the sun''s return; the reading is interpretive and not stated by the text.'),
('event.hindu.sita_abduction_rescue','HEROIC_CONFLICT','Tretā yuga (in the tradition''s own chronology)','Kaikeyī''s boons send Rāma into exile; Rāvaṇa abducts Sītā.','Alliance with the vānaras, Hanumān''s search, the bridge to Laṅkā and the war.','Rāvaṇa is slain, Sītā passes through fire and Rāma is crowned in Ayodhyā.','Book VII (Uttara Kāṇḍa), with Sītā''s second exile, is not retold here.');

INSERT OR IGNORE INTO claims(
    id,subject_id,predicate,object_entity_id,object_literal,object_datatype,statement,variant_group,claim_status,confidence,confidence_level,review_status,assertion_scope,knowledge_layer,tradition_scope,temporal_scope,research_notes,created_at
) VALUES
('claim.v0320.xiyouji_havoc.01','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'born from a stone egg on the Mountain of Flowers and Fruit','string','A stone on the Mountain of Flowers and Fruit splits into a stone egg that becomes a monkey whose eyes flash light to heaven.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.02','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'leaps through the waterfall and becomes Handsome Monkey King','string','The stone monkey leaps through the waterfall, finds the Water Curtain Cave and is acclaimed Handsome Monkey King.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.03','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'sails away on a raft to seek the secret of long life','string','Grieving that the King of the Dead will one day claim him, the Monkey King sails alone across the sea to seek immortality.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.04','hero.chinese.subodhi_patriarch','NARRATIVE_ACTION',NULL,'names the monkey Sun Wukong','string','Patriarch Subodhi receives the monkey at the Cave of the Slanting Moon and Three Stars and names him Sun Wukong.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.05','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'learns the seventy-two transformations and the somersault cloud','string','Understanding the patriarch''s three blows as a riddle, Wukong is secretly taught long life, the seventy-two transformations and the somersault cloud.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.06','hero.chinese.subodhi_patriarch','NARRATIVE_ACTION',NULL,'expels Wukong for showing off and forbids him to name his teacher','string','After Wukong shows off by becoming a pine tree, the patriarch expels him and forbids him ever to name his teacher.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.07','deity.chinese.ao_guang','NARRATIVE_ACTION',NULL,'yields the ocean-fixing iron, the Compliant Golden-Hooped Rod','string','Ao Guang, Dragon King of the Eastern Sea, lets Sun Wukong take the 13,500-pound iron that becomes the Compliant Golden-Hooped Rod.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.08','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'strikes the monkeys'' names from the Register of Life and Death','string','Dragged to the underworld in a dream, Wukong strikes his own name and those of all monkeys from the Register of Life and Death.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.09','deity.chinese.jade_emperor','NARRATIVE_ACTION',NULL,'appoints Wukong Keeper of the Heavenly Horses','string','On Venus''s advice the Jade Emperor summons Wukong to heaven and appoints him Keeper of the Heavenly Horses, a post without rank.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.10','deity.chinese.jade_emperor','NARRATIVE_ACTION',NULL,'grants the empty title Great Sage Equal to Heaven','string','After Heavenly King Li and Nezha fail to capture him, the Jade Emperor grants Wukong the empty title Great Sage Equal to Heaven and builds him a mansion.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.11','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'eats the immortal peaches he was set to guard','string','Put in charge of the Garden of Immortal Peaches, Wukong secretly eats the ripest peaches and learns he is not invited to the Peach Banquet.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.12','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'steals the banquet wine and Laozi''s elixir, then defeats heaven''s army','string','Wukong drinks the banquet wine, eats Laozi''s elixir pills and holds off a hundred thousand heavenly soldiers at his mountain.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.13','deity.chinese.erlang_shen','NARRATIVE_ACTION',NULL,'matches the Great Sage''s transformations and captures him','string','Erlang matches every transformation of the Great Sage until Laozi''s Diamond Snare and Erlang''s hound bring him down.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.14','deity.chinese.taishang_laojun','NARRATIVE_ACTION',NULL,'refines the Great Sage in the Eight Trigrams furnace for forty-nine days','string','Laozi refines the captured Great Sage in his Eight Trigrams furnace for forty-nine days; he emerges with fiery golden eyes and kicks the furnace over.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.15','deity.chinese.rulai_xiyouji','NARRATIVE_ACTION',NULL,'wagers that the Great Sage cannot leave his palm','string','Rulai wagers that the Great Sage cannot somersault out of his right palm; the monkey leaps and reaches five pink pillars he takes for the edge of heaven.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.xiyouji_havoc.16','deity.chinese.rulai_xiyouji','NARRATIVE_ACTION',NULL,'pins the Great Sage under the Mountain of Five Elements','string','Rulai reveals the Great Sage''s graffiti on his own finger and turns his hand into the Mountain of Five Elements, pinning the monkey beneath it.','v0320.xiyouji_havoc','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.01','deity.chinese.li_jing','NARRATIVE_ACTION',NULL,'his wife carries Nezha for three years and six months','string','Li Jing''s wife Lady Yin carries her third child for three years and six months and dreams of a Daoist handing her a ''unicorn child''.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.02','deity.chinese.nezha','NARRATIVE_ACTION',NULL,'born from a ball of flesh, wearing the Universe Ring and the Red Armillary Sash','string','Li Jing cuts open the ball of flesh and a glowing boy springs out wearing a golden ring on his arm and a red silk sash.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.03','hero.chinese.taiyi_zhenren','NARRATIVE_ACTION',NULL,'names the child Nezha and takes him as his disciple','string','Taiyi Zhenren of the Golden Light Cave names the child Nezha and takes him as his disciple.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.04','deity.chinese.nezha','NARRATIVE_ACTION',NULL,'shakes the Crystal Palace by swishing his sash in the river','string','At seven, bathing in the Nine Bends River, Nezha swishes his sash in the water and shakes the Dragon King''s Crystal Palace.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.05','deity.chinese.nezha','KILLED','dragon.chinese.ao_bing',NULL,NULL,'Nezha kills the patrolling yaksha Li Gen with his ring and then the Dragon King''s third son Ao Bing, whose sinew he pulls out.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.06','deity.chinese.ao_guang','NARRATIVE_ACTION',NULL,'vows to accuse Li Jing and Nezha before the Jade Emperor','string','Ao Guang comes to Chentang Pass in human form, finds Nezha braiding his son''s sinew, and vows to accuse Li Jing and Nezha before the Jade Emperor.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.07','deity.chinese.nezha','NARRATIVE_ACTION',NULL,'beats Ao Guang at the gate of heaven and pockets him as a small snake','string','Made invisible by Taiyi''s charm, Nezha ambushes Ao Guang outside the Gate of Treasured Virtue, tears off his scales and carries him home as a little green snake.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.08','deity.chinese.nezha','NARRATIVE_ACTION',NULL,'kills Lady Shiji''s disciple with an arrow from the Universe Bow','string','Nezha draws the Yellow Emperor''s Universe Bow and his arrow kills the Green Cloud boy, disciple of Lady Shiji.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.09','hero.chinese.taiyi_zhenren','NARRATIVE_ACTION',NULL,'burns Lady Shiji back into her stone form with the Nine-Dragon Divine Fire Cover','string','Taiyi Zhenren traps Lady Shiji under his Nine-Dragon Divine Fire Cover and burns her back into her original form, a stone.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.10','deity.chinese.nezha','NARRATIVE_ACTION',NULL,'returns his flesh and bones to his parents to save them','string','To free his parents from the four dragon kings, Nezha cuts open his body and returns his flesh and bones to his parents, and dies.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.11','deity.chinese.li_jing','NARRATIVE_ACTION',NULL,'smashes Nezha''s statue and burns his shrine on Cuiping Mountain','string','Finding pilgrims at the shrine his wife secretly built for Nezha on Cuiping Mountain, Li Jing smashes the statue and burns the shrine.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.12','hero.chinese.taiyi_zhenren','NARRATIVE_ACTION',NULL,'rebuilds Nezha from lotus and gives him the fire-tipped spear and wind-and-fire wheels','string','Taiyi Zhenren rebuilds Nezha''s body from lotus stems and leaves with an elixir pill and gives him the fire-tipped spear and the wind-and-fire wheels.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.fengshen_nezha.13','deity.chinese.li_jing','NARRATIVE_ACTION',NULL,'receives the golden pagoda and the title Pagoda-Bearing Heavenly King','string','Pursued by the reborn Nezha, Li Jing receives the golden pagoda from Randeng Daoren, which forces Nezha to acknowledge him and gives him the title Pagoda-Bearing Heavenly King.','v0320.fengshen_nezha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Investiture of the Gods (Ming novel)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.01','text.greek.theogony','NARRATIVE_ACTION',NULL,'the Muses give Hesiod a laurel staff and the gift of song','string','Hesiod says the Muses gave him a laurel staff and a divine voice beneath Helicon and asks them to tell how the gods first came to be.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.02','deity.greek.chaos','NARRATIVE_ACTION',NULL,'comes to be first of all','string','In the Theogony Chaos comes to be first, followed by Earth, Tartarus and Eros; Earth then bears starry Heaven, the hills and the sea.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.03','deity.greek.gaia','NARRATIVE_ACTION',NULL,'bears the Titans, the Cyclopes and the Hundred-Handers','string','Earth and Heaven produce the twelve Titans, youngest of them Cronus, together with the three Cyclopes and the three Hundred-Handers.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.04','deity.greek.cronus','NARRATIVE_ACTION',NULL,'castrates Ouranos with Earth''s sickle','string','With a sickle of adamant made by Earth, Cronus ambushes Heaven and castrates him; from the blood come the Erinyes, the Giants and the Meliai.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.05','deity.greek.aphrodite','NARRATIVE_ACTION',NULL,'born from the sea-foam and comes ashore at Cyprus','string','Aphrodite grows from the foam around Heaven''s severed members, comes ashore at Cythera and Cyprus, and is attended by Eros and Desire.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.06','deity.greek.nyx','NARRATIVE_ACTION',NULL,'bears Doom, Death, Sleep, the Fates and Strife without a partner','string','Night, alone, bears Doom, Death, Sleep, Dreams, the Fates, Nemesis and Strife, while the line of Sea produces Nereus, the Gorgons, Echidna and her monstrous brood.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.07','deity.greek.hecate','NARRATIVE_ACTION',NULL,'given a share of honour in earth, sea and heaven by Zeus','string','Zeus honours Hecate above all, granting her a share of earth, sea and starry heaven; she gives success to those she favours.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.08','deity.greek.cronus','NARRATIVE_ACTION',NULL,'swallows his children as they are born','string','Warned that a son will overthrow him, Cronus swallows each child Rhea bears: Hestia, Demeter, Hera, Hades and Poseidon.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.09','deity.greek.rhea','NARRATIVE_ACTION',NULL,'saves Zeus by giving Cronus a swaddled stone','string','Rhea bears Zeus secretly in Crete and gives Cronus a stone in swaddling clothes to swallow; Cronus later vomits up the stone and his children.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.10','deity.greek.prometheus','NARRATIVE_ACTION',NULL,'tricks Zeus at Mecone and steals fire in a fennel stalk','string','At Mecone Prometheus tricks Zeus over the sacrifice and then steals fire in a fennel stalk; Zeus chains him and sends an eagle to eat his liver until Heracles frees him.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.11','deity.greek.hephaestus','NARRATIVE_ACTION',NULL,'moulds the first woman from earth at Zeus''s will','string','At Zeus''s will Hephaestus moulds the first woman from earth and Athena adorns her, as Zeus''s answer to the theft of fire.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.12','deity.greek.zeus','NARRATIVE_ACTION',NULL,'frees the Hundred-Handers and wins their alliance','string','After ten years of indecisive war, Zeus follows Earth''s advice, brings the Hundred-Handers up to the light and wins their alliance against the Titans.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.13','deity.greek.zeus','NARRATIVE_ACTION',NULL,'defeats the Titans with thunderbolts and the Hundred-Handers'' rocks','string','Zeus unleashes his thunderbolts while the Hundred-Handers hurl three hundred rocks at a time, and the Titans are cast down beneath the earth in chains.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.14','realm.greek.tartarus','DESCRIBED_AS',NULL,'as far below the earth as heaven is above it; an anvil falls nine days to reach it','string','Hesiod places Tartarus as far below the earth as heaven is above, a bronze anvil falling nine days to reach it, with the houses of Night, Sleep, Death, Hades and Styx nearby.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.15','deity.greek.zeus','NARRATIVE_ACTION','creature.greek.typhon',NULL,NULL,'Zeus strikes the hundred-headed Typhoeus with lightning, burns his heads and hurls him into Tartarus.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.theogony.16','deity.greek.zeus','NARRATIVE_ACTION',NULL,'chosen king of the gods; swallows Metis and bears Athena from his head','string','The gods ask Zeus to reign on Earth''s advice; he swallows Metis to forestall a son who would overthrow him, bears Athena from his head and takes his later wives.','v0320.theogony','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Hesiod, Theogony (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.01','deity.greek.hades','NARRATIVE_ACTION',NULL,'seizes Persephone on the Nysian plain','string','As Persephone reaches for a narcissus that Earth grew by Zeus''s will, the ground opens on the Nysian plain and Hades carries her off in his golden chariot.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.02','deity.greek.hecate','NARRATIVE_ACTION',NULL,'hears Persephone''s cry from her cave','string','Of all gods and mortals only Hecate in her cave and Helios hear Persephone''s cry for help.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.03','deity.greek.demeter','NARRATIVE_ACTION',NULL,'searches for nine days with blazing torches','string','Demeter tears off her headband, puts on a dark cloak and searches the earth for nine days with torches, refusing ambrosia, nectar and bathing.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.04','deity.greek.helios','NARRATIVE_ACTION',NULL,'tells Demeter that Zeus gave her daughter to Hades','string','Helios tells Demeter that Zeus gave Persephone to his brother Hades as wife, urging her that Hades is no unworthy son-in-law.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.05','deity.greek.demeter','NARRATIVE_ACTION',NULL,'disguised as the old woman Doso, becomes a nurse in Eleusis','string','Angry with Zeus, Demeter leaves Olympus, sits disguised as an old woman named Doso at the Maiden Well in Eleusis, and is taken into King Celeus''s house as a nurse.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.06','deity.greek.demeter','NARRATIVE_ACTION',NULL,'laughs at Iambe''s jests and drinks barley, water and pennyroyal','string','Silent with grief in Celeus''s house, Demeter is brought to laugh by Iambe''s jests and asks for a drink of barley, water and pennyroyal instead of wine.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.07','deity.greek.demeter','NARRATIVE_ACTION',NULL,'lays Demophoon in the fire at night to make him immortal','string','Demeter nurses Demophoon with ambrosia and secretly lays him in the fire at night to make him immortal, until Metaneira sees and cries out.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.08','deity.greek.demeter','NARRATIVE_ACTION',NULL,'reveals herself and demands a temple at Eleusis','string','Demeter takes Demophoon from the fire, reveals her divinity, and demands a temple and altar above the Callichorus well where she will teach her rites.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.09','deity.greek.demeter','NARRATIVE_ACTION',NULL,'causes a year-long famine by hiding the seed','string','Sitting apart in her new Eleusinian temple, Demeter hides the seed so that nothing grows, bringing a famine that threatens humankind and the gods'' offerings.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.10','deity.greek.demeter','NARRATIVE_ACTION',NULL,'refuses every god''s plea until she sees her daughter','string','Demeter rejects Iris and then all the gods sent by Zeus, vowing not to return to Olympus or let the earth bear fruit until she sees her daughter.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.11','deity.greek.hades','NARRATIVE_ACTION',NULL,'secretly gives Persephone a pomegranate seed before releasing her','string','Obeying Zeus''s message brought by Hermes, Hades releases Persephone but secretly gives her a pomegranate seed so that she cannot stay forever with her mother.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.12','deity.greek.persephone','NARRATIVE_ACTION',NULL,'must spend a third of each year below and return each spring','string','Reunited with Demeter, Persephone learns that because she ate below she must spend a third of each year under the earth and return each spring.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.13','deity.greek.rhea','NARRATIVE_ACTION',NULL,'brings Zeus''s promise and urges Demeter to end the famine','string','Zeus sends Rhea to Demeter with his promise of honours and of Persephone''s yearly return; Rhea urges her to end the famine.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.demeter_long.14','deity.greek.demeter','NARRATIVE_ACTION',NULL,'restores the harvest and teaches the Eleusinian mysteries','string','Demeter makes the fields bear again and teaches her rites and mysteries to Triptolemus, Diocles, Eumolpus and Celeus before returning to Olympus.','v0320.demeter_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Hymn 2 to Demeter (Evelyn-White translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.01','deity.norse.thor','NARRATIVE_ACTION',NULL,'raises his goats from their bones and takes Þjálfi and Röskva as servants','string','Thor raises his slaughtered goats with Mjöllnir; finding one lame because Þjálfi split its bone, he takes Þjálfi and Röskva as servants.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.02','deity.norse.thor','NARRATIVE_ACTION',NULL,'shelters for a night in the giant Skrýmir''s glove','string','Travelling into Jötunheimr, Thor and his companions spend a night in what proves to be the glove of the giant Skrýmir.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.03','deity.norse.thor','NARRATIVE_ACTION',NULL,'strikes the sleeping Skrýmir three times without harming him','string','Thor cannot untie Skrýmir''s provision bag and strikes the sleeping giant three times with his hammer, but the giant only asks whether a leaf, an acorn or bird droppings fell on him.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.04','being.norse.utgarda_loki','NARRATIVE_ACTION',NULL,'mocks Thor and demands a contest of skills','string','Útgarða-Loki mocks Thor as a ''little lad'' and demands that each visitor prove some skill before he may stay.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.05','deity.norse.loki','NARRATIVE_ACTION',NULL,'loses an eating contest to Logi','string','Loki loses an eating contest to Logi, who devours the meat, the bones and the trough itself.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.06','hero.norse.thjalfi','NARRATIVE_ACTION',NULL,'loses three races to Hugi','string','Þjálfi races Hugi three times and loses each heat by a wider margin.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.07','deity.norse.thor','NARRATIVE_ACTION',NULL,'fails to empty the drinking horn in three draughts','string','Thor drinks three mighty draughts from Útgarða-Loki''s penalty horn but cannot empty it.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.08','deity.norse.thor','NARRATIVE_ACTION',NULL,'lifts only one paw of the grey cat','string','Straining his utmost, Thor manages to lift only one paw of Útgarða-Loki''s grey cat from the floor.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.09','deity.norse.thor','NARRATIVE_ACTION',NULL,'is forced to one knee by the old woman Elli','string','Thor wrestles Útgarða-Loki''s old nurse Elli and is forced down onto one knee.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.10','being.norse.utgarda_loki','NARRATIVE_ACTION',NULL,'reveals that the contests were illusions: fire, thought, the sea, the Serpent and old age','string','Útgarða-Loki reveals he was Skrýmir and that Thor''s opponents were wildfire, thought, the sea, the Midgard Serpent and old age.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.11','deity.norse.thor','NARRATIVE_ACTION',NULL,'raises his hammer as Útgarða-Loki and his castle vanish','string','When Thor raises his hammer, Útgarða-Loki and his stronghold vanish, leaving only open plains; Thor resolves to meet the Midgard Serpent again.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.thor_utgard.12','deity.norse.thor','NARRATIVE_ACTION',NULL,'hooks the Midgard Serpent while fishing with Hymir','string','Fishing with the giant Hymir using an ox head for bait, Thor hooks the Midgard Serpent and hauls it to the boat before Hymir cuts the line.','v0320.thor_utgard','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.01','deity.norse.baldr','NARRATIVE_ACTION',NULL,'dreams that his life is threatened','string','Baldr dreams ominous dreams threatening his life, and the Æsir resolve to secure protection for him against every danger.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.02','deity.norse.frigg','NARRATIVE_ACTION',NULL,'takes oaths from all things not to harm Baldr','string','Frigg takes oaths from fire, water, metals, stones, earth, trees, sicknesses, beasts, birds, poisons and snakes not to harm Baldr.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.03','deity.norse.loki','NARRATIVE_ACTION',NULL,'learns of the unsworn mistletoe and pulls it up','string','Disguised as a woman, Loki learns from Frigg that the young mistletoe west of Valhöll swore no oath, and pulls it up.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.04','deity.norse.hodr','KILLED','deity.norse.baldr',NULL,NULL,'Guided by Loki, the blind Höðr throws the mistletoe, which pierces Baldr and kills him.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.05','deity.norse.odin','NARRATIVE_ACTION',NULL,'grieves most, understanding the loss best','string','Odin bears Baldr''s death most heavily of all the gods, understanding best what a loss it is for the Æsir.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.06','deity.norse.hermod','NARRATIVE_ACTION',NULL,'rides Sleipnir to Hel to ransom Baldr','string','At Frigg''s request Hermóðr the Bold, Odin''s son, mounts Sleipnir and rides to Hel to ransom Baldr.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.07','deity.norse.nanna_nepsdottir','NARRATIVE_ACTION',NULL,'dies of grief and is burned with Baldr on Hringhorni','string','At Baldr''s ship-funeral his wife Nanna dies of grief and is burned beside him, while Odin lays the ring Draupnir on the pyre.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.08','deity.norse.hermod','NARRATIVE_ACTION',NULL,'rides nine nights to the Gjallarbrú','string','Hermóðr rides nine nights through dark valleys to the Gjallarbrú, where the maiden Móðguðr tells him the road to Hel lies downward and north.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.09','deity.norse.hel','NARRATIVE_ACTION',NULL,'will release Baldr only if all things weep for him','string','Hel agrees to release Baldr only if all things in the world, living and dead, weep for him; if any refuses, he stays.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.10','deity.norse.frigg','NARRATIVE_ACTION',NULL,'all things weep for Baldr at the gods'' request','string','The Æsir send messengers through the world, and men, beasts, earth, stones, trees and metals all weep for Baldr.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.11','deity.norse.loki','NARRATIVE_ACTION',NULL,'as the giantess Þökk refuses to weep for Baldr','string','A giantess named Þökk, believed to be Loki, alone refuses to weep for Baldr, so he remains in Hel.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.12','deity.norse.thor','NARRATIVE_ACTION',NULL,'catches Loki, in salmon form, by the tail','string','When Loki, as a salmon, tries to leap over the gods'' net in the Fránangr falls, Thor catches him by the tail.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.baldr_long.13','deity.norse.sigyn','NARRATIVE_ACTION',NULL,'holds a bowl under the venom dripping onto the bound Loki','string','With Loki bound by his son''s entrails beneath Skaði''s serpent, Sigyn holds a bowl to catch the venom; when she empties it, his writhing causes earthquakes.','v0320.baldr_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Snorri Sturluson, Edda: Gylfaginning',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.01','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'saw the Deep and built the wall of Uruk','string','The prologue of the Standard Babylonian epic presents Gilgamesh as the one who saw the Deep, built the wall of Uruk and recorded his labours on a stone tablet.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.02','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'two-thirds god, oppresses the people of Uruk','string','Two-thirds god and one-third man, Gilgamesh oppresses the young men and women of Uruk until the people cry out to the gods.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.03','hero.mesopotamian.enkidu','NARRATIVE_ACTION',NULL,'made by Aruru from clay thrown into the wild','string','The goddess Aruru pinches off clay and throws it into the wild, making the hairy Enkidu, who lives among the gazelles and frees the trapper''s prey.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.04','hero.mesopotamian.enkidu','NARRATIVE_ACTION',NULL,'gains human understanding through Shamhat','string','After six days and seven nights with Shamhat, Enkidu is shunned by the beasts but gains understanding, while Gilgamesh dreams of the companion who is coming.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.05','hero.mesopotamian.enkidu','NARRATIVE_ACTION',NULL,'wrestles Gilgamesh at the bridal door and becomes his friend','string','Civilised with bread and beer among the shepherds, Enkidu bars Gilgamesh from a bridal house in Uruk; after wrestling like bulls, the two become friends.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.06','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'resolves to kill Humbaba to win lasting fame','string','Seeking lasting fame because human days are numbered, Gilgamesh resolves to kill Humbaba of the Cedar Forest, and Ninsun prays to Shamash for him.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.07','hero.mesopotamian.enkidu','NARRATIVE_ACTION',NULL,'interprets Gilgamesh''s dreams on the road as favourable','string','On the road to the Cedar Forest, Enkidu interprets each of Gilgamesh''s terrifying dreams as a favourable omen.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.08','deity.akkadian.shamash','NARRATIVE_ACTION',NULL,'sends thirteen winds that pin Humbaba','string','Shamash sends thirteen winds that pin Humbaba in place, allowing Gilgamesh and Enkidu to kill him despite his pleas.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.09','deity.akkadian.ishtar','NARRATIVE_ACTION',NULL,'proposes marriage to Gilgamesh and is refused','string','Ishtar proposes marriage to Gilgamesh, who refuses her by recounting the fates of her former lovers, from Dumuzi to the gardener Ishullanu.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.10','hero.sumerian.gilgamesh','KILLED','creature.mesopotamian.bull_of_heaven',NULL,NULL,'With Enkidu holding the Bull of Heaven by its horns, Gilgamesh drives his sword between its nape and horns and kills it.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.11','hero.mesopotamian.enkidu','NARRATIVE_ACTION',NULL,'is condemned by the gods, falls sick and dies after twelve days','string','The gods decree that Enkidu must die for the deaths of Humbaba and the Bull of Heaven; he curses and then blesses Shamhat, dreams of the House of Dust, and dies after twelve days.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.12','hero.sumerian.gilgamesh','MOURNS','hero.mesopotamian.enkidu',NULL,NULL,'Gilgamesh laments Enkidu, veils his face like a bride''s, paces like a lioness bereft of her cubs, and commissions a statue of gold and lapis lazuli.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.13','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'walks twelve double-hours of darkness through Mount Mashu','string','Fearing death, Gilgamesh passes the scorpion-people of Mount Mashu and walks twelve double-hours of darkness to a garden of jewelled trees.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.14','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'crosses the Waters of Death to Uta-napishti','string','Guided by the alewife Siduri and the boatman Urshanabi, Gilgamesh crosses the Waters of Death with three hundred punting poles and reaches Uta-napishti.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.15','hero.mesopotamian.utnapishtim','NARRATIVE_ACTION',NULL,'survives the Flood and is granted eternal life','string','Uta-napishti tells how Ea warned him through a reed wall, how he built a boat and survived the six-day Flood, released a dove, a swallow and a raven, and was granted eternal life by Enlil.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.gilgamesh_sb.16','hero.sumerian.gilgamesh','NARRATIVE_ACTION',NULL,'fails the test of sleep and loses the plant of rejuvenation to a snake','string','Gilgamesh fails Uta-napishti''s test of staying awake, wins the plant ''An Old Man Grows Young'' from the deep, loses it to a snake, and returns to the walls of Uruk.','v0320.gilgamesh_sb','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Standard Babylonian Gilgamesh (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.01','deity.babylonian.tiamat','NARRATIVE_ACTION',NULL,'mingles her waters with Apsû before anything was named','string','Before heaven and earth were named, Apsû and Tiamat mingle their waters, and from them are born Lahmu and Lahamu, Anshar and Kishar, Anu and Ea.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.02','deity.babylonian.apsu','NARRATIVE_ACTION',NULL,'plots to destroy the noisy young gods','string','Disturbed by the young gods'' noise, Apsû plots with his vizier Mummu to destroy them, though Tiamat objects to destroying their own offspring.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.03','deity.babylonian.ea','KILLED','deity.babylonian.apsu',NULL,NULL,'Ea puts Apsû to sleep with a pure incantation, takes his crown and aura, kills him and builds his own dwelling upon him.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.04','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'born with four eyes, four ears and fire on his lips','string','Marduk is born to Ea and Damkina with four eyes and four ears and fiery lips; Anu gives him the four winds, with which he troubles Tiamat.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.05','deity.babylonian.tiamat','NARRATIVE_ACTION',NULL,'creates eleven monsters and gives Qingu the Tablet of Destinies','string','Urged to avenge Apsû, Tiamat brings forth eleven monsters, makes Qingu commander of her host and fastens the Tablet of Destinies on his breast.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.06','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'agrees to fight Tiamat if the gods make his word supreme','string','After Ea and Anu both turn back from Tiamat, Marduk offers to fight her on condition that the gods make his word decree destinies.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.07','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'has his destiny decreed by the gods at a banquet','string','At a banquet summoned by Anshar, the great gods eat, drink and then assemble to decree Marduk''s destiny as their avenger.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.08','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'makes a garment vanish and reappear by his word; proclaimed king','string','The gods test Marduk''s word by having him make a garment vanish and reappear, then proclaim him king and give him sceptre, throne and weapon.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.09','deity.babylonian.marduk','USES','weapon.babylonian.marduk_bow',NULL,NULL,'Marduk arms himself with bow, mace, lightning, a net held by the four winds, seven destructive winds, the Flood-weapon and a storm chariot drawn by four poisonous steeds.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.10','deity.babylonian.marduk','KILLED','deity.babylonian.tiamat',NULL,NULL,'In single combat Marduk nets Tiamat, drives the evil wind into her open mouth and shoots an arrow through her belly and heart.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.11','deity.babylonian.kingu','NARRATIVE_ACTION',NULL,'is captured and stripped of the Tablet of Destinies','string','Captured by Marduk after Tiamat''s fall, Qingu is stripped of the Tablet of Destinies, which Marduk seals and fastens on his own breast.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.12','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'makes sky and earth from Tiamat''s body and orders the stars and months','string','Marduk splits Tiamat''s body like a dried fish, making the sky from one half and the earth from the other, opening the Tigris and Euphrates from her eyes and ordering stars, months and the moon.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.13','deity.babylonian.ea','CREATOR_OF',NULL,'creates humankind from Qingu''s blood to bear the gods'' toil','string','On Marduk''s plan Ea creates humankind from the blood of the condemned Qingu, so that humans bear the gods'' toil.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.enuma_elish_long.14','deity.babylonian.marduk','NARRATIVE_ACTION',NULL,'honoured with Babylon, Esagila and fifty names','string','The Anunnaki build Babylon and the temple Esagila for Marduk, and the gods proclaim his fifty names.','v0320.enuma_elish_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Enūma eliš (eBL corpus)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.01','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'abandons seven temples and sets her mind on the netherworld','string','Inana sets her mind on the great below and abandons heaven, earth, her priestly offices and seven temples in seven cities.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.02','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'adorns herself with seven divine powers as regalia','string','Inana takes up the seven divine powers as regalia: crown, wig, lapis beads, egg-shaped beads, pala dress, eye-paint and pectoral, gold ring and measuring rod and line.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.03','deity.sumerian.ninshubur','NARRATIVE_ACTION',NULL,'is instructed to lament and seek help from Enlil, Nanna and Enki','string','Inana instructs Ninšubur to lament for her and to seek help from Enlil, then Nanna, then Enki if she does not return.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.04','deity.sumerian.ereshkigal','NARRATIVE_ACTION',NULL,'orders the seven gates bolted and Inana stripped as she enters','string','Told that Inana has come for her husband''s funeral rites, Ereškigala orders the seven gates bolted and Inana stripped of her regalia as she enters.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.05','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'is stripped of one item of regalia at each of the seven gates','string','At each of the seven gates one of Inana''s regalia is removed, and each time she is told to be satisfied, for a divine power of the netherworld has been fulfilled.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.06','deity.sumerian.ereshkigal','NARRATIVE_ACTION',NULL,'turns Inana into a corpse with the look of death','string','When Inana sits on her throne, Ereškigala fixes her with the look of death, and the Anuna judges condemn her; Inana becomes a corpse hung on a hook.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.07','deity.sumerian.enlil','NARRATIVE_ACTION',NULL,'refuses to help Inana, who craved the netherworld''s powers','string','When Ninšubur pleads for Inana after three days and nights, Enlil angrily refuses, saying whoever craves the netherworld''s powers must remain there; Nanna also refuses.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.08','deity.sumerian.enki','CREATOR_OF',NULL,'creates two rescuers from the dirt under his fingernails','string','Enki creates the kur-ĝara and the gala-tura from the dirt under his fingernails and sends them with the plant and water of life to rescue Inana.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.09','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'is revived with the plant and water of life','string','Enki''s creatures win Ereškigala''s gratitude, refuse her gifts, take Inana''s corpse from the hook and revive her with the plant and water of life.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.10','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'must provide a substitute and is escorted by the galla demons','string','The Anuna let Inana ascend only if she provides a substitute, and the galla demons who know no food, drink or gifts go up with her.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.11','deity.sumerian.inanna','NARRATIVE_ACTION',NULL,'spares Ninšubur, Šara and Lulal because they mourned for her','string','Inana refuses to hand Ninšubur, Šara or Lulal to the demons because each mourned for her in dirty garments.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.inanna_long.12','deity.sumerian.dumuzi','NARRATIVE_ACTION',NULL,'is handed over as Inana''s substitute and flees with snake''s hands and feet','string','Found enthroned and unmourning, Dumuzid is given to the demons by Inana; Utu changes his hands and feet into snake''s so he can escape, and the broken ending divides the year between him and his sister.','v0320.inanna_long','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Inana''s Descent to the Netherworld (ETCSL 1.4.1)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.01','deity.egyptian.thoth','NARRATIVE_ACTION',NULL,'wins five epagomenal days from the Moon','string','In Plutarch''s account Hermes (Thoth) wins a seventieth part of each day''s light from the Moon at draughts and composes the five epagomenal days, on which Rhea (Nut) can give birth.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.02','deity.egyptian.osiris','NARRATIVE_ACTION',NULL,'born on the first epagomenal day','string','Plutarch lists the births on the five added days: Osiris, Arueris (the elder Horus), Typhon who bursts through his mother''s side, Isis and Nephthys.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.03','deity.egyptian.osiris','NARRATIVE_ACTION',NULL,'teaches cultivation, laws and worship','string','Plutarch says Osiris as king taught the Egyptians cultivation, laws and worship, then civilised the world by persuasion and music rather than weapons.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.04','deity.egyptian.seth','NARRATIVE_ACTION',NULL,'traps Osiris in a sealed chest','string','In Plutarch''s account Typhon (Seth) and seventy-two conspirators trap Osiris in a chest made to his measure, seal it with nails and molten lead and send it to the sea by the Tanitic mouth.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.05','deity.egyptian.isis','MOURNS','deity.egyptian.osiris',NULL,NULL,'Plutarch says that on hearing of the murder Isis cut a lock of her hair at Coptos, put on mourning and searched everywhere, learning the river mouth from children at play.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.06','deity.egyptian.isis','NARRATIVE_ACTION',NULL,'rears the abandoned child Anubis','string','In Plutarch''s account Isis, guided by dogs, finds and rears the child Nephthys abandoned for fear of Typhon; he becomes her guardian Anubis.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.07','deity.egyptian.isis','NARRATIVE_ACTION',NULL,'seeks the coffin enclosed in a pillar at Byblos','string','Plutarch tells that the chest lodged in a heather tree at Byblos, which grew around it; the king made the trunk a pillar of his palace, and Isis came to Byblos and sat weeping by a spring.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.08','deity.egyptian.isis','NARRATIVE_ACTION',NULL,'takes the coffin from the pillar at Byblos','string','Plutarch says Isis, as nurse to the Byblian prince, burned away his mortality by night until the queen''s cry broke the rite; then she revealed herself and took the coffin from the pillar.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.09','deity.egyptian.isis','MOURNS','deity.egyptian.osiris',NULL,NULL,'Plutarch describes Isis opening the chest in a solitary place, laying her face on Osiris''s face and weeping; the Byblian boy who sees her dies at her look.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.10','deity.egyptian.seth','NARRATIVE_ACTION',NULL,'tears the body into fourteen parts','string','In Plutarch''s account Typhon (Seth), hunting by moonlight, finds the body of Osiris, tears it into fourteen parts and scatters them; Isis recovers them in a papyrus boat.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.11','deity.egyptian.horus','NARRATIVE_ACTION',NULL,'prevails over Typhon after many days of battle','string','Plutarch says Osiris returned from the other world to train Horus, who answers that the noblest deed is to avenge one''s parents, and who prevails over Typhon after many days of battle.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.plutarch_osiris.12','deity.egyptian.isis','NARRATIVE_ACTION',NULL,'releases the captured Typhon','string','Plutarch says Isis released the captured Typhon, Horus tore the diadem from her head, the gods with Hermes'' help judged Horus legitimate, and the tomb of Osiris is placed on an inaccessible island near Philae.','v0320.plutarch_osiris','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Plutarch, De Iside et Osiride (Greek reception of the Osiris myth)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.01','deity.japanese.izanagi','NARRATIVE_ACTION',NULL,'divides the realms among his three noble children','string','Izanagi gives Amaterasu his jewel necklace and the Plain of High Heaven, Tsukuyomi the dominion of night and Susanoo the plain of the sea.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.02','deity.japanese.susanoo','NARRATIVE_ACTION',NULL,'weeps until mountains wither and is expelled','string','Susanoo weeps until his beard grows long, the mountains wither and the seas dry, saying he wants to go to his mother''s land; Izanagi expels him.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.03','deity.japanese.amaterasu','NARRATIVE_ACTION',NULL,'arms herself to meet Susanoo','string','Fearing that Susanoo comes to seize her land, Amaterasu binds her hair like a man, arms herself with jewels, quivers and bow and stamps the earth as she waits for him.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.04','deity.japanese.amaterasu','NARRATIVE_ACTION',NULL,'swears the oath of child-bearing with Susanoo','string','Across the Tranquil River of Heaven Amaterasu crunches Susanoo''s sabre and blows out three goddesses, and Susanoo crunches her jewels and blows out five male deities.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.05','deity.japanese.susanoo','NARRATIVE_ACTION',NULL,'claims victory in the oath','string','Amaterasu assigns the five male deities to herself and the three goddesses to Susanoo, who claims that his gentle daughters prove his pure heart and that he has won.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.06','deity.japanese.susanoo','NARRATIVE_ACTION',NULL,'ravages the Plain of High Heaven','string','Susanoo breaks Amaterasu''s rice-field ridges, defiles her hall and flings a backward-flayed piebald horse into her weaving hall, causing a weaving maiden''s death.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.07','deity.japanese.amaterasu','NARRATIVE_ACTION','event.japanese.ame_no_iwato',NULL,NULL,'Terrified, Amaterasu shuts herself in the Heavenly Rock-Dwelling, so that Heaven and the Central Land of Reed-Plains fall into continual night and calamities arise.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.08','deity.japanese.omoikane','NARRATIVE_ACTION',NULL,'devises the plan to draw Amaterasu out','string','The eight hundred myriad deities assemble in the bed of the Tranquil River of Heaven and have Omoikane devise a plan: singing birds, a mirror, a string of jewels and divination by a stag''s shoulder-blade.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.09','deity.japanese.ame_no_tajikarao','NARRATIVE_ACTION',NULL,'hides beside the door of the Rock-Dwelling','string','The deities hang jewels, a mirror and cloth offerings on a sakaki tree from Mount Kagu; Futotama holds it, Ame-no-Koyane recites a liturgy and Tajikarao hides beside the door.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.10','deity.japanese.ame_no_uzume','NARRATIVE_ACTION',NULL,'dances before the Rock-Dwelling until the deities laugh','string','Ame-no-Uzume stamps on an upturned tub before the Rock-Dwelling, becomes divinely possessed and bares herself, so that the Plain of High Heaven shakes with the laughter of the deities.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.11','deity.japanese.ame_no_tajikarao','NARRATIVE_ACTION','deity.japanese.amaterasu',NULL,NULL,'When Amaterasu opens the door a crack and is shown the mirror, Ame-no-Tajikarao draws her out by the hand and Futotama stretches a rope behind her, and light returns.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.12','deity.japanese.susanoo','NARRATIVE_ACTION','deity.japanese.ogetsuhime',NULL,NULL,'Expelled from Heaven, Susanoo kills the food goddess Ōgetsuhime, and silkworms, rice, millet, beans and barley grow from her body; Kami-musubi takes them as seeds.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.13','monster.japanese.yamata_no_orochi','DESCRIBED_AS',NULL,'eight heads and eight tails, spanning eight valleys and eight hills','string','Ashinazuchi tells Susanoo that the eight-forked serpent of Koshi, with eight heads and eight tails, eyes like red winter-cherries and a body spanning eight valleys and hills, has devoured seven of his eight daughters.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.14','deity.japanese.susanoo','NARRATIVE_ACTION','weapon.japanese.kusanagi',NULL,NULL,'Susanoo makes the eight-forked serpent drunk with eight vats of liquor, cuts it to pieces, finds a great sword in its middle tail and presents it to Amaterasu.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.kojiki_iwato_orochi.15','deity.japanese.susanoo','NARRATIVE_ACTION',NULL,'builds the palace of Suga and sings of the eightfold fence','string','Susanoo builds his palace at Suga in Izumo, saying his heart is refreshed, sings the song of the eightfold fence as clouds rise, and makes Ashinazuchi master of the palace.','v0320.kojiki_iwato_orochi','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Kojiki (Chamberlain 1882 translation)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.01','text.indian.ramayana','NARRATIVE_ACTION',NULL,'opens with the grief that became the first śloka','string','The opening cantos tell how Vālmīki''s grief at a hunter killing a curlew became the first śloka and how Brahmā commanded him to sing the story of Rāma in that metre.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.02','deity.hindu.vishnu','NARRATIVE_ACTION',NULL,'agrees to be born as the sons of Daśaratha to slay Rāvaṇa','string','At the gods'' plea against Rāvaṇa, whose boon protected him from gods and demons but not men, Vishnu agrees to be born as the four sons of Daśaratha, who receives the divine rice-milk from his sacrificial fire.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.03','deity.hindu.rama','NARRATIVE_ACTION',NULL,'guards Viśvāmitra''s sacrifice and slays Tāṭakā','string','Lent to Viśvāmitra to guard his sacrifice, Rāma slays the rākṣasī Tāṭakā at the sage''s urging, receives the divine weapons and drives off Mārīca and Subāhu.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.04','deity.hindu.rama','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'At Mithilā Rāma lifts, strings and breaks the bow of Śiva that no king could lift, and Janaka gives him Sītā, the daughter found in a furrow.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.05','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'is bound by two boons to exile Rāma','string','Persuaded by her maid Mantharā, Kaikeyī claims Daśaratha''s two old boons: Bharata''s consecration and Rāma''s exile to the forest for fourteen years.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.06','deity.hindu.sita','NARRATIVE_ACTION',NULL,'insists on following Rāma into exile','string','When Rāma accepts exile without a change of face, Sītā insists that a wife shares her husband''s lot and follows him into the forest with Lakṣmaṇa, all three in bark garments.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.07','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'dies of grief, fulfilling an old curse','string','After Rāma leaves, Daśaratha tells Kausalyā how in youth he shot a young ascetic by mistake and was cursed by the boy''s blind father to die grieving for a son, and dies at midnight.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.08','hero.indian.bharata','NARRATIVE_ACTION',NULL,'rules Ayodhyā in the name of Rāma''s sandals','string','Refusing the throne, Bharata seeks Rāma at Citrakūṭa; when Rāma will not break their father''s word, Bharata takes his sandals, sets them on the throne and rules from Nandigrāma as their servant.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.09','hero.indian.lakshmana','NARRATIVE_ACTION',NULL,'cuts off Śūrpaṇakhā''s nose and ears','string','At Pañcavaṭī, when the rākṣasī Śūrpaṇakhā, rebuffed by both brothers, attacks Sītā, Lakṣmaṇa cuts off her nose and ears at Rāma''s command, and Rāma then destroys the army of Khara and Dūṣaṇa alone.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.10','demon.hindu.ravana','NARRATIVE_ACTION',NULL,'sends Mārīca as a golden deer to lure Rāma away','string','Rāvaṇa forces Mārīca to take the form of a golden deer, which lures Rāma away; dying, Mārīca cries out in Rāma''s voice so that Sītā sends Lakṣmaṇa after him.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.11','demon.hindu.ravana','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Disguised as an ascetic, Rāvaṇa seizes Sītā and carries her to Laṅkā, cutting down the vulture-king Jaṭāyu who tries to stop him, while Sītā drops her ornaments to five monkeys.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.12','deity.hindu.rama','NARRATIVE_ACTION',NULL,'performs funeral rites for the vulture Jaṭāyu','string','Finding the hut empty, Rāma learns from the dying Jaṭāyu that Rāvaṇa took Sītā south, cremates the vulture as a father, and is directed by Kabandha to seek Sugrīva.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.13','deity.hindu.rama','NARRATIVE_ACTION',NULL,'allies with Sugrīva and shoots Vālin from concealment','string','Rāma allies with Sugrīva through Hanumān, shoots Vālin from concealment and answers his reproach, makes Sugrīva king and gives his ring to Hanumān for the southern search.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.14','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'leaps the hundred-league sea to Laṅkā','string','Told by Sampāti that Sītā is in Laṅkā and reminded by Jāmbavān of his strength, Hanumān leaps the hundred-league sea from Mount Mahendra, passing Maināka, Surasā and Siṃhikā.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.15','deity.hindu.hanuman','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Hanumān finds Sītā in the aśoka grove after Rāvaṇa threatens her, gives her Rāma''s ring, and receives her crest-jewel when she declines to be carried away by him.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.16','deity.hindu.hanuman','NARRATIVE_ACTION','place.hindu.lanka',NULL,NULL,'Captured by Indrajit and sentenced by Rāvaṇa, Hanumān has his tail set alight, feels no heat through Sītā''s prayer, and burns Laṅkā before leaping back with her crest-jewel.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.17','deity.hindu.rama','NARRATIVE_ACTION',NULL,'crosses to Laṅkā by the bridge built by Nala','string','Rāma grants refuge to Vibhīṣaṇa and, after the Ocean rises at his threatened arrow, has Nala build a bridge to Laṅkā in five days and lays siege to the city.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.18','hero.indian.lakshmana','NARRATIVE_ACTION',NULL,'slays Indrajit','string','In the war before Laṅkā Garuḍa frees the brothers from Indrajit''s serpent-arrows, Rāma slays Kumbhakarṇa, Hanumān brings the mountain of herbs, and Lakṣmaṇa slays Indrajit.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.19','deity.hindu.rama','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'In single combat, with Indra''s chariot driven by Mātali, Rāma strikes off Rāvaṇa''s regrowing heads and finally kills him with the weapon of Brahmā, then tells Vibhīṣaṇa that enmity ends with death.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z'),
('claim.v0320.ramayana_griffith.20','deity.hindu.sita','NARRATIVE_ACTION',NULL,'passes through fire and is restored to Rāma','string','After Rāma''s harsh public words Sītā enters a pyre and Agni returns her unharmed and declares her pure; the gods proclaim Rāma to be Nārāyaṇa, and Rāma returns to Ayodhyā to be crowned.','v0320.ramayana_griffith','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-11T01:00:00Z');

