INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0320.chinese_xiyouji_ch1_7.1','storyver.chinese.xiyouji_ch1_7',1,'仙石孕出石猴','A stone gives birth to a monkey','东胜神洲傲来国的海外，有一座花果山，山顶上立着一块仙石。','Beyond the sea from the land of Aolai on the Eastern Continent stands the Mountain of Flowers and Fruit, and on its summit an immortal stone that had absorbed the essences of heaven and earth since the world began.','claim.v0320.xiyouji_havoc.01','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.2','storyver.chinese.xiyouji_ch1_7',2,'水帘洞里的美猴王','King of the Water Curtain Cave','石猴在山中和群猴一起玩耍，饿了吃草木果实，渴了喝山涧泉水。','The monkey played among the other monkeys of the mountain.','claim.v0320.xiyouji_havoc.02','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.3','storyver.chinese.xiyouji_ch1_7',3,'为死亡而哭','Weeping over death','有一天，美猴王和群猴正在饮宴，他忽然流下泪来。','One day at a feast the Monkey King suddenly wept.','claim.v0320.xiyouji_havoc.03','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.4','storyver.chinese.xiyouji_ch1_7',4,'斜月三星洞','The Cave of the Slanting Moon and Three Stars','木筏被风吹到南赡部洲。','The raft carried him to the Southern Continent, where for eight or nine years he learned human speech and dress but met only people chasing fame and profit.','claim.v0320.xiyouji_havoc.04','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.5','storyver.chinese.xiyouji_ch1_7',5,'三更时分的秘传','A secret lesson at the third watch','悟空在洞中扫地、挑水、砍柴，一住就是六七年。','Wukong swept, fetched water and cut wood for six or seven years.','claim.v0320.xiyouji_havoc.05','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.6','storyver.chinese.xiyouji_ch1_7',6,'卖弄被逐，回山除魔','Showing off, and sent home','一天傍晚，众师兄围着悟空，要看他学来的变化。','One evening his fellow students begged to see his new powers, and Wukong turned himself into a pine tree to their loud applause.','claim.v0320.xiyouji_havoc.06','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.7','storyver.chinese.xiyouji_ch1_7',7,'东海龙宫借宝','A weapon from the Dragon King','悟空操练群猴，却没有一件称手的兵器。','Needing a weapon, Wukong dived to the Crystal Palace of Ao Guang, Dragon King of the Eastern Sea.','claim.v0320.xiyouji_havoc.07','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.8','storyver.chinese.xiyouji_ch1_7',8,'勾销生死簿','Striking out the Register of Death','悟空回山后，又与牛魔王等六位妖王结为兄弟，天天宴饮。','After a drunken feast with six demon kings, Wukong dreamed that two summoners roped his soul and dragged it to the Land of Darkness.','claim.v0320.xiyouji_havoc.08','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.9','storyver.chinese.xiyouji_ch1_7',9,'天庭的第一份官职：弼马温','Heaven''s first office: Keeper of the Horses','玉帝看了两道表文，正要派兵捉拿，太白金星出班奏道：这猴子是天地育成之体，不如降一道招安圣旨，把他宣上天来，给他一个官职，拘束在此，若他受天命，以后再加升赏；若违天命，就地擒拿。','As the Jade Emperor prepared to send troops, the Gold Star of Venus advised him to summon the monkey with a decree of amnesty and keep him in heaven under a title.','claim.v0320.xiyouji_havoc.09','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.10','storyver.chinese.xiyouji_ch1_7',10,'齐天大圣','Great Sage Equal to Heaven','悟空在洞门外竖起一面大旗，上书“齐天大圣”四个大字。','Wukong raised a banner reading ''Great Sage Equal to Heaven''.','claim.v0320.xiyouji_havoc.10','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.11','storyver.chinese.xiyouji_ch1_7',11,'蟠桃园','The Garden of Immortal Peaches','大圣在天上无事可做，今天东游，明天西荡，和众星宿称兄道弟。','With nothing to do, the Great Sage wandered heaven befriending stars.','claim.v0320.xiyouji_havoc.11','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.12','storyver.chinese.xiyouji_ch1_7',12,'偷酒偷丹，十万天兵','Stolen wine, stolen elixir and heaven''s army','大圣用定身法把七位仙女定在树下，驾云直奔瑶池。','Freezing the fairies with an immobilising spell, the Great Sage flew to the Jade Pool, put the wine-makers to sleep with sleep-insects made from his hairs and drank himself senseless.','claim.v0320.xiyouji_havoc.12','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.13','storyver.chinese.xiyouji_ch1_7',13,'二郎神斗法','The contest with Erlang','观音菩萨赴蟠桃会，听说此事，先派徒弟惠岸行者下界交战，也败了回来。','Guanyin recommended the Jade Emperor''s nephew, the Illustrious Sage Erlang of Guanjiang.','claim.v0320.xiyouji_havoc.13','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.14','storyver.chinese.xiyouji_ch1_7',14,'八卦炉中的火眼金睛','Fiery golden eyes in the Eight Trigrams furnace','大圣被押到斩妖台，绑在降妖柱上。','Bound at the execution terrace, the Great Sage could not be hurt by sword, axe, fire or thunder: the peaches, wine and elixir had made his body adamantine.','claim.v0320.xiyouji_havoc.14','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.15','storyver.chinese.xiyouji_ch1_7',15,'如来的手掌','The palm of the Buddha','王灵官和三十六员雷将把大圣团团围住，大圣变出三头六臂，把金箍棒幌一幌变成三根，六只手使开，打得雷将们近不了身。','Surrounded by Wang Lingguan and thirty-six thunder generals, the Great Sage fought them off with three heads, six arms and three staffs, until the Jade Emperor sent to the West for Rulai.','claim.v0320.xiyouji_havoc.15','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_xiyouji_ch1_7.16','storyver.chinese.xiyouji_ch1_7',16,'五行山下','Under the Mountain of Five Elements','大圣心想：我到了这里，回去跟如来做个凭证。','To prove his journey he made a brush from a hair, wrote ''The Great Sage Equal to Heaven was here'' on the middle pillar, and relieved himself at the foot of the first.','claim.v0320.xiyouji_havoc.16','event.chinese.havoc_in_heaven','place.chinese.huaguo_shan','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','“五百年”的时间与后来唐僧解救的情节见于第八回之后，本篇只讲到被压为止。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.1','storyver.chinese.fengshen_ch12_14',1,'三年六个月的身孕','Three years and six months','商朝末年，陈塘关的总兵李靖，曾经拜西昆仑度厄真人为师，学过五行遁术，后来因为仙道难成，下山辅佐纣王，做了镇守一方的总兵。','In the last years of the Shang, Li Jing, commander of Chentang Pass, had once studied the arts of the Five Elements with an immortal before coming down the mountain to serve King Zhou.','claim.v0320.fengshen_nezha.01','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.2','storyver.chinese.fengshen_ch12_14',2,'肉球里跳出的孩子','A child from a ball of flesh','两个侍女慌慌张张跑来报告：夫人生下了一个妖精！','Maids ran out crying that their mistress had given birth to a monster.','claim.v0320.fengshen_nezha.02','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.3','storyver.chinese.fengshen_ch12_14',3,'太乙真人收徒','Taiyi Zhenren takes a disciple','第三天，门官来报：外面有一位道人求见。','On the third day a Daoist called: Taiyi Zhenren of the Golden Light Cave on Qianyuan Mountain.','claim.v0320.fengshen_nezha.03','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.4','storyver.chinese.fengshen_ch12_14',4,'九湾河洗澡','Bathing in the Nine Bends River','光阴似箭，哪吒长到七岁，身高六尺。','At seven years old and six feet tall, Nezha went outside the pass one hot day in the fifth month with a servant.','claim.v0320.fengshen_nezha.04','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.5','storyver.chinese.fengshen_ch12_14',5,'夜叉与三太子','The yaksha and the third prince','龙王派巡海夜叉李艮去看看出了什么事。','The Dragon King sent the patrolling yaksha Li Gen to investigate.','claim.v0320.fengshen_nezha.05','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.6','storyver.chinese.fengshen_ch12_14',6,'龙王上门','The Dragon King comes calling','哪吒回到家里，若无其事。','Ao Guang, grieving for his son, came to Chentang Pass in the form of a scholar and demanded the killer.','claim.v0320.fengshen_nezha.06','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.7','storyver.chinese.fengshen_ch12_14',7,'宝德门外痛打龙王','Beating the Dragon King at the Gate of Treasured Virtue','哪吒借土遁到乾元山，向太乙真人说明经过。','Nezha travelled underground to his teacher.','claim.v0320.fengshen_nezha.07','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','宝德门一段跨第十二、十三回回末与回首，各刻本分回处略有出入。','2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.8','storyver.chinese.fengshen_ch12_14',8,'一箭射死碧云童子','An arrow kills the Green Cloud boy','龙王放回后，怀恨而去。','Freed, the Dragon King left nursing his grudge.','claim.v0320.fengshen_nezha.08','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.9','storyver.chinese.fengshen_ch12_14',9,'石矶娘娘现出原形','Lady Shiji shown as stone','哪吒来到骷髅山，和石矶娘娘一言不合就动起手来。','At Skull Mountain Nezha fought Lady Shiji, who caught his ring and sash with her eight-trigram cloud-light kerchief.','claim.v0320.fengshen_nezha.09','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.10','storyver.chinese.fengshen_ch12_14',10,'剔骨还父，割肉还母','Returning his bones to his father and his flesh to his mother','原来东海龙王敖光不甘心，约了南海、西海、北海三位龙王，一起上奏玉帝。','Ao Guang had gathered the dragon kings of the southern, western and northern seas, and with the Jade Emperor''s warrant they seized Li Jing and Lady Yin.','claim.v0320.fengshen_nezha.10','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.11','storyver.chinese.fengshen_ch12_14',11,'翠屏山的行宫','The shrine on Cuiping Mountain','哪吒的魂魄飘飘荡荡，来到乾元山。','Nezha''s soul drifted to his teacher, who told him to appear in his mother''s dreams and ask for a shrine on Cuiping Mountain, forty li from the pass; after three years of incense he could return to the world.','claim.v0320.fengshen_nezha.11','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.12','storyver.chinese.fengshen_ch12_14',12,'莲花化身','A body made of lotus','太乙真人叫金霞童子到五莲池摘两枝莲花、三片荷叶来。','Taiyi had his servant fetch two lotus flowers and three lotus leaves from the Five-Lotus Pond.','claim.v0320.fengshen_nezha.12','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.chinese_fengshen_ch12_14.13','storyver.chinese.fengshen_ch12_14',13,'父子相争与玲珑宝塔','Father against son, and the golden pagoda','哪吒踏着风火轮，提着火尖枪，直奔陈塘关找李靖算账。','Riding his wind-and-fire wheels with the fire-tipped spear, Nezha stormed Chentang Pass in pursuit of his father.','claim.v0320.fengshen_nezha.13','event.chinese.nezha_sea_uproar',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','追赶途中几位师长出面的细节较多，此处只概述；燃灯赐塔与“托塔天王”之名见第十四回。','2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.1','storyver.greek.theogony_long',1,'赫利孔山下的牧人','A shepherd under Helicon','诗人赫西俄德说，他从赫利孔山的缪斯们开始歌唱。','Hesiod begins with the Muses of Helicon, the nine daughters of Zeus and Memory, who dance by the springs of the mountain and walk down at night veiled in mist, praising the gods.','claim.v0320.theogony.01','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.2','storyver.greek.theogony_long',2,'最初是卡俄斯','First came Chaos','最先出现的是卡俄斯——一片张开的空隙。','Verily at the first Chaos came to be — a gaping void — and then broad-breasted Earth, the ever-sure foundation of the gods of Olympus; dim Tartarus in the depth of the earth; and Eros, fairest of the gods, who loosens the limbs and overcomes the mind.','claim.v0320.theogony.02','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.3','storyver.greek.theogony_long',3,'天空的孩子们','The children of Heaven','后来大地与天空相爱，生下了深深漩涡的大洋神俄刻阿诺斯，还有科俄斯、克利俄斯、许珀里翁、伊阿佩托斯，以及忒亚、瑞亚、忒弥斯、谟涅摩叙涅、头戴金冠的福柏和可爱的忒堤斯——这些就是十二位提坦。','Then Earth lay with Heaven and bore deep-swirling Oceanus, Coeus and Crius, Hyperion and Iapetus, Theia and Rhea, Themis and Mnemosyne, gold-crowned Phoebe and lovely Tethys — the Titans — and after them the youngest, wily Cronus, most terrible of her children, who hated his lusty father.','claim.v0320.theogony.03','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.4','storyver.greek.theogony_long',4,'大地的镰刀','The sickle of Earth','天空乌拉诺斯憎恨自己的孩子们，每当一个孩子出生，他就把他们藏进大地的深处，不让他们见到光明，并以这种恶行为乐。','Heaven hated his children and hid each of them, as soon as it was born, in the depths of Earth, rejoicing in his wickedness while vast Earth groaned within.','claim.v0320.theogony.04','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.5','storyver.greek.theogony_long',5,'从浪花中诞生','Born from the foam','克洛诺斯割下的部分从陆地被抛进波涛汹涌的大海，随着海浪漂流了很久，四周泛起白色的泡沫，泡沫中生长出一位少女。','The members, cast from the land into the surging sea, drifted a long time, and white foam spread around them; in it grew a maiden.','claim.v0320.theogony.05','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','荷马史诗说阿佛洛狄忒是宙斯与狄俄涅之女；本站把两种出身作为不同见证分开保存。','2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.6','storyver.greek.theogony_long',6,'黑夜的子女与海中的怪物','The children of Night and the monsters of the sea','乌拉诺斯称他的孩子们为“提坦”，意思是“伸手的人”，因为他们胆敢伸手犯下大罪，日后必遭报应。','Heaven called his sons Titans, ''strainers'', for they had strained to do a fearful deed.','claim.v0320.theogony.06','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.7','storyver.greek.theogony_long',7,'赫卡忒的荣耀','The honours of Hecate','提坦们也有了后代：许珀里翁和忒亚生下了伟大的太阳赫利俄斯、明亮的月亮塞勒涅和照耀大地的黎明厄俄斯；大洋神的女儿斯堤克斯生下了热望、胜利、强力和暴力。','The Titans had children too: Hyperion and Theia bore great Helios, bright Selene and Eos who shines on all.','claim.v0320.theogony.07','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.8','storyver.greek.theogony_long',8,'吞下孩子的克洛诺斯','Cronus swallows his children','瑞亚被克洛诺斯征服，为他生下了出色的孩子们：赫斯提亚、得墨忒耳、脚穿金鞋的赫拉、住在地下、心肠无情的哈得斯、撼动大地的波塞冬，还有众神与人类之父、睿智的宙斯。','Rhea, subdued by Cronus, bore splendid children: Hestia, Demeter, gold-shod Hera, pitiless Hades who dwells under the earth, the loud-crashing Earth-Shaker, and wise Zeus, father of gods and men.','claim.v0320.theogony.08','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.9','storyver.greek.theogony_long',9,'克里特山洞里的婴儿','The baby in the Cretan cave','当瑞亚就要生下宙斯的时候，她恳求自己的父母——大地和星空——帮她想个办法，悄悄生下这个孩子，好为她的父亲和被吞下的孩子们向克洛诺斯复仇。','When Rhea was about to bear Zeus, she begged Earth and Heaven to help her bear him secretly and avenge her father and her swallowed children.','claim.v0320.theogony.09','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.10','storyver.greek.theogony_long',10,'墨科涅的分肉与盗火','The division at Mecone and the theft of fire','提坦伊阿佩托斯的儿子中，有扛着天穹的阿特拉斯、狂傲的墨诺提俄斯、聪明多计的普罗米修斯和糊涂的厄庇米修斯。','Among the sons of Iapetus were Atlas, who holds up the sky, proud Menoetius, clever Prometheus and witless Epimetheus.','claim.v0320.theogony.10','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.11','storyver.greek.theogony_long',11,'第一个女人','The first woman','为了补偿火的代价，宙斯给人类送去了一样祸害。','In return for fire Zeus made an evil for men.','claim.v0320.theogony.11','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','《神谱》中的第一个女人没有名字；“潘多拉”与她打开罐子的故事见于赫西俄德《工作与时日》，本篇不合并。','2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.12','storyver.greek.theogony_long',12,'被释放的百臂巨人','The Hundred-Handers set free','当初乌拉诺斯嫉妒科托斯、布里阿瑞俄斯和古革斯的力量与身形，用强大的锁链把他们捆住，囚禁在宽广大地的尽头，他们在那里长久地忍受痛苦与悲伤。','Ouranos, jealous of the strength and shape of Cottus, Briareos and Gyes, had bound them in cruel chains at the ends of the earth.','claim.v0320.theogony.12','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.13','storyver.greek.theogony_long',13,'泰坦之战','The war with the Titans','那一天，男神和女神都投入了可怕的战斗。','That day gods and goddesses joined in fearful strife.','claim.v0320.theogony.13','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.14','storyver.greek.theogony_long',14,'塔耳塔罗斯','Tartarus','提坦们被关进的地方，离大地之下的距离，就像天空离大地那么远：一块青铜的铁砧从天上落下，要九天九夜，第十天才到地面；再从地面落下，又要九天九夜，第十天才到塔耳塔罗斯。','The Titans lie as far beneath the earth as heaven is above it: a bronze anvil falling from heaven would fall nine nights and days and reach the earth on the tenth, and as long again to reach Tartarus.','claim.v0320.theogony.14','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.15','storyver.greek.theogony_long',15,'最后的敌人提丰','The last enemy, Typhoeus','宙斯把提坦们赶出天界之后，广大的大地与塔耳塔罗斯结合，生下了她最小的孩子提丰。','When Zeus had driven the Titans from heaven, Earth lay with Tartarus and bore her youngest child, Typhoeus, with tireless feet and a hundred snake heads flickering dark tongues and flashing fire from their eyes.','claim.v0320.theogony.15','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_theogony_long.16','storyver.greek.theogony_long',16,'宙斯为王','Zeus becomes king','当有福的众神结束了苦战，以武力决定了与提坦们的荣誉之争，他们听从大地的建议，敦促目光远大的奥林波斯之神宙斯来统治和主宰他们，宙斯便在众神中公平地分配了各自的荣誉。','When the gods had finished their toil and settled their honours with the Titans by force, they urged Zeus, on Earth''s advice, to reign over them, and he divided their honours.','claim.v0320.theogony.16','event.greek.theogony_succession',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.1','storyver.norse.utgard_gylf',1,'复活的山羊','The goats raised from their bones','有一次，索尔驾着他的山羊车出门，洛基与他同行。','Thor once drove out in his goat chariot with Loki and lodged at a farmer''s.','claim.v0320.thor_utgard.01','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.2','storyver.norse.utgard_gylf',2,'巨人的手套','The giant''s glove','索尔把山羊留在农夫家，带着洛基、夏尔菲和罗斯克娃向东走，渡过深深的大海，来到巨人之国约顿海姆。','Leaving the goats, Thor went east with Loki, Þjálfi and Röskva across the deep sea into Jötunheimr.','claim.v0320.thor_utgard.02','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.3','storyver.norse.utgard_gylf',3,'解不开的口袋，打不醒的巨人','A bag he could not open, a giant he could not wake','斯克里米尔提议和他们结伴同行，把干粮合在一起，装进他的一个口袋里背着。','Skrýmir proposed they travel together and put all the provisions in his bag.','claim.v0320.thor_utgard.03','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.4','storyver.norse.utgard_gylf',4,'乌特加尔城','The stronghold of Útgarðr','索尔一行继续前进，中午时分看见平原上矗立着一座城堡，高得他们要把头仰到脖子贴着后背才能看到顶。','They went on and at noon saw a stronghold on a plain so tall that they had to bend their heads back to their spines to see over it.','claim.v0320.thor_utgard.04','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.5','storyver.norse.utgard_gylf',5,'洛基比吃','Loki''s eating contest','站在最后面的洛基先开口说：我有一样本领，敢和人比赛——没有人能比我吃得更快。','Loki, standing last, said he could eat faster than anyone.','claim.v0320.thor_utgard.05','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.6','storyver.norse.utgard_gylf',6,'夏尔菲赛跑','Þjálfi''s race','乌特加尔洛基又问那个年轻人会什么。','Asked what the young man could do, Þjálfi offered to race anyone.','claim.v0320.thor_utgard.06','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.7','storyver.norse.utgard_gylf',7,'喝不干的角杯','The horn that would not empty','国王问索尔愿意表演什么本领，人们都说他是个大英雄。','Asked for his feat, Thor chose drinking.','claim.v0320.thor_utgard.07','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.8','storyver.norse.utgard_gylf',8,'举不起的灰猫','The grey cat','乌特加尔洛基说：现在很清楚，你的力气并不像我们想象的那么大。','Útgarða-Loki remarked that Thor was clearly not as strong as they had thought, and offered a game the young men play, of little account: lifting his cat.','claim.v0320.thor_utgard.08','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.9','storyver.norse.utgard_gylf',9,'与老妇人角力','Wrestling the old woman','索尔大怒道：你们既然说我矮小，那就叫个人出来和我摔跤吧，我现在正发着火呢！','Angry, Thor demanded someone to wrestle.','claim.v0320.thor_utgard.09','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.10','storyver.norse.utgard_gylf',10,'真相','The truth','第二天清晨，索尔一行准备上路，乌特加尔洛基亲自送他们出城。','In the morning Útgarða-Loki escorted them out and, beyond the walls, told the truth: he had deceived them with illusions and would never let Thor in again.','claim.v0320.thor_utgard.10','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.11','storyver.norse.utgard_gylf',11,'消失的城堡','The vanished castle','乌特加尔洛基接着说：现在我们分手吧，你们最好别再来找我，我会用同样的幻术来保护我的城堡，让你们对我无可奈何。','Útgarða-Loki bade them part and never return, for he would defend his stronghold with such tricks again.','claim.v0320.thor_utgard.11','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_utgard_gylf.12','storyver.norse.utgard_gylf',12,'垂钓世界之蛇','Fishing for the World Serpent','没过多久，索尔装扮成一个年轻人，独自来到巨人希米尔家里借宿。','Soon after, Thor, disguised as a young man, lodged with the giant Hymir and insisted on going fishing with him.','claim.v0320.thor_utgard.12','event.norse.thor_utgard',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','斯诺里说“有人说”锤子打掉了蛇头，但他认为世界之蛇仍然活着；两种说法本站都保留。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.1','storyver.babylonian.gilgamesh_sb',1,'看见深渊的人','He who saw the Deep','史诗这样开头：他看见了深渊，看见了大地的根基；他知道一切的道路，无所不晓。','The epic opens: he who saw the Deep, the foundation of the land, who knew the ways and was wise in all things; who saw what was secret, uncovered what was hidden, and brought back word from before the Flood.','claim.v0320.gilgamesh_sb.01','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','人物“吉尔伽美什”在本站以苏美尔诗篇实体登记，此处按巴比伦史诗讲述。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.2','storyver.babylonian.gilgamesh_sb',2,'三分之二是神','Two-thirds god','吉尔伽美什的母亲是野牛女神宁孙，父亲是英雄卢伽尔班达。','Gilgamesh, son of the wild-cow goddess Ninsun and the hero Lugalbanda, was tall and mighty, two-thirds god and one-third man, rampaging through Uruk like a wild bull with no equal.','claim.v0320.gilgamesh_sb.02','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.3','storyver.babylonian.gilgamesh_sb',3,'泥土里走出的野人','A wild man made of clay','阿鲁鲁听了，在心中构想出一个形象。','Aruru conceived an image in her heart, washed her hands, pinched off clay and threw it into the wild, and there she made valiant Enkidu.','claim.v0320.gilgamesh_sb.03','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.4','storyver.babylonian.gilgamesh_sb',4,'夏姆哈特与两个梦','Shamhat and two dreams','猎人带着夏姆哈特在水坑边等了三天。','The trapper and Shamhat waited three days at the waterhole until Enkidu came with the beasts.','claim.v0320.gilgamesh_sb.04','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.5','storyver.babylonian.gilgamesh_sb',5,'面包、啤酒与一场摔跤','Bread, beer and a wrestling match','夏姆哈特把自己的衣服分一半给恩奇都穿上，牵着他的手来到牧人的营地。','Shamhat dressed Enkidu in half her clothing and led him to the shepherds'' camp.','claim.v0320.gilgamesh_sb.05','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','摔跤与结为朋友一段的细节部分依据古巴比伦版补足，标准版此处有残缺。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.6','storyver.babylonian.gilgamesh_sb',6,'去雪松林','To the Cedar Forest','吉尔伽美什对恩奇都说：在雪松林里住着凶猛的胡姆巴巴，是恩利尔派他守护森林的。','Gilgamesh proposed to Enkidu that they go to the Cedar Forest and kill fierce Humbaba, whom Enlil had appointed to guard it, and so win eternal fame.','claim.v0320.gilgamesh_sb.06','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.7','storyver.babylonian.gilgamesh_sb',7,'一路上的梦','Dreams along the road','两人上路了。','They set out, covering in a day what others walk in a month and a half, and on the third day reached the mountains of Lebanon.','claim.v0320.gilgamesh_sb.07','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.8','storyver.babylonian.gilgamesh_sb',8,'胡姆巴巴之死','The death of Humbaba','他们站在雪松林的边上，凝望高大的雪松，看见胡姆巴巴走过的小路。','At the edge of the forest they gazed at the cedars and the track Humbaba walked, the mountain of cedars where the gods dwell.','claim.v0320.gilgamesh_sb.08','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.9','storyver.babylonian.gilgamesh_sb',9,'伊什塔尔的求婚','Ishtar''s proposal','回到乌鲁克，吉尔伽美什洗净长发，擦亮兵器，换上干净的衣服，戴上王冠。','Back in Uruk, Gilgamesh washed his hair, polished his weapons and put on his crown.','claim.v0320.gilgamesh_sb.09','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.10','storyver.babylonian.gilgamesh_sb',10,'天牛','The Bull of Heaven','伊什塔尔怒不可遏，登上天庭，哭着找到父亲安努和母亲安图，说吉尔伽美什一再侮辱她。','Enraged, Ishtar went weeping to her father Anu and mother Antu, and demanded the Bull of Heaven to kill Gilgamesh, threatening otherwise to smash the gates of the underworld and raise the dead to eat the living.','claim.v0320.gilgamesh_sb.10','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.11','storyver.babylonian.gilgamesh_sb',11,'众神的判决','The verdict of the gods','那天夜里，恩奇都做了一个梦：众神召开会议，安努对恩利尔说，他们杀死了天牛，又杀死了胡姆巴巴，两人中必须有一个死去。','That night Enkidu dreamed the gods in council: because they had killed the Bull of Heaven and Humbaba, one of the two must die, and Enlil decreed it should be Enkidu.','claim.v0320.gilgamesh_sb.11','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.12','storyver.babylonian.gilgamesh_sb',12,'为恩奇都哀哭','The lament for Enkidu','天刚亮，吉尔伽美什就为朋友哀哭：恩奇都，我的朋友，荒野里的野驴、草原上的豹子，乌鲁克的长老、雪松林的小路、你曾饮水的河流，都为你哭泣吧！','At first light Gilgamesh lamented: let the wild asses and leopards, the elders of Uruk, the paths of the Cedar Forest and the rivers where Enkidu drank all weep for him.','claim.v0320.gilgamesh_sb.12','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.13','storyver.babylonian.gilgamesh_sb',13,'黑暗的山路','The road through the darkness','吉尔伽美什在荒野里游荡，痛哭不止：我死了，不也会像恩奇都一样吗？','Gilgamesh wandered the wild weeping: shall I not die like Enkidu?','claim.v0320.gilgamesh_sb.13','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.14','storyver.babylonian.gilgamesh_sb',14,'渡过死亡之水','Across the Waters of Death','海边住着一位酿酒的女主人西杜丽。','By the sea lived the alewife Siduri, who barred her door at the sight of this gaunt, skin-clad wanderer.','claim.v0320.gilgamesh_sb.14','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.15','storyver.babylonian.gilgamesh_sb',15,'大洪水','The Flood','吉尔伽美什问：你和我一样，怎么能站在众神的集会中，得到永生？','How, asked Gilgamesh, had Uta-napishti joined the gods'' assembly and found life?','claim.v0320.gilgamesh_sb.15','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_gilgamesh_sb.16','storyver.babylonian.gilgamesh_sb',16,'睡眠的考验与偷走的仙草','The test of sleep and the stolen plant','乌特纳皮什提说：可是现在，谁会为你召集众神，让你得到你寻求的永生呢？','Who, asked Uta-napishti, would assemble the gods for him?','claim.v0320.gilgamesh_sb.16','event.babylonian.gilgamesh_epic','site.iraq.uruk','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.1','storyver.egyptian.plutarch_ch12_20',1,'从月亮那里赢来的五天','Five days won from the Moon','普鲁塔克这样开头：瑞亚——埃及人叫她努特，是天空女神——和克洛诺斯（大地之神盖布）偷偷结合。','Plutarch begins with Rhea — the Egyptian sky goddess Nut — who lay secretly with Cronus, the earth god Geb.','claim.v0320.plutarch_osiris.01','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','普鲁塔克用希腊神名：瑞亚对应努特，克洛诺斯对应盖布，赫尔墨斯对应托特；对应关系是他的解释。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.2','storyver.egyptian.plutarch_ch12_20',2,'五位神的生日','Five birthdays','第一天，奥西里斯降生。','On the first day Osiris was born, and a voice proclaimed that the Lord of All had come into the light; some say a man named Pamyles, drawing water at the temple of Zeus in Thebes, heard a voice ordering him to announce that a great and beneficent king, Osiris, was born.','claim.v0320.plutarch_osiris.02','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“大荷鲁斯”（阿鲁埃里斯）与伊西斯之子荷鲁斯在普鲁塔克那里是两位；本站的荷鲁斯条目不把两者合并为单一判断。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.3','storyver.egyptian.plutarch_ch12_20',3,'不用武器的国王','A king without weapons','奥西里斯做了埃及的国王。','Osiris, as king, freed the Egyptians from a destitute and brutish way of life: he showed them the fruits of cultivation, gave them laws and taught them to honour the gods.','claim.v0320.plutarch_osiris.03','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.4','storyver.egyptian.plutarch_ch12_20',4,'量身定做的木箱','The made-to-measure chest','奥西里斯回来以后，提丰设下了阴谋。','When Osiris returned, Typhon plotted against him with seventy-two conspirators and a queen from Ethiopia named Aso.','claim.v0320.plutarch_osiris.04','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“第二十八年”也有人解释为奥西里斯的年龄；普鲁塔克两说并存。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.5','storyver.egyptian.plutarch_ch12_20',5,'剪下一绺头发','A lock of hair','最先知道这件事的，是住在凯姆米斯附近的潘神和萨提尔们，他们把消息传开——所以直到今天，人们把突如其来的恐慌叫做“潘神之惧”。','The first to learn of the deed were the Pans and Satyrs who lived near Chemmis, and they spread the news — which is why sudden alarms are still called panics.','claim.v0320.plutarch_osiris.05','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.6','storyver.egyptian.plutarch_ch12_20',6,'被遗弃的孩子','The abandoned child','在寻找的途中，伊西斯得知了一件事：奥西里斯曾在不知情的情况下与奈芙蒂斯同寝，把她当成了伊西斯。','On her search Isis learned that Osiris, mistaking Nephthys for herself, had unwittingly lain with her; the proof was a garland of melilot he had left with her.','claim.v0320.plutarch_osiris.06','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','阿努比斯的父母在埃及本土资料中有不同说法；这里只是普鲁塔克的版本。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.7','storyver.egyptian.plutarch_ch12_20',7,'长进树里的棺木','The coffin inside the tree','后来伊西斯打听到，那只箱子被海浪冲到了腓尼基的比布鲁斯，搁浅在一丛石楠上。','Isis then learned that the chest had been washed ashore at Byblos in Phoenicia, in the branches of a heather bush, which quickly grew into a large and beautiful tree, enclosing the chest entirely within its trunk.','claim.v0320.plutarch_osiris.07','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.8','storyver.egyptian.plutarch_ch12_20',8,'火里的王子','The prince in the fire','王后闻到侍女身上的香气，就派人把这位陌生女子请进宫里，让她做了小王子的保姆。','The queen, smelling the fragrance on her maids, sent for the stranger and made her nurse to the baby prince.','claim.v0320.plutarch_osiris.08','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这一段与《荷马颂歌·致得墨忒耳》中得墨忒耳在厄琉息斯把婴儿放进火里的情节非常相似，学者常把两者对照。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.9','storyver.egyptian.plutarch_ch12_20',9,'船上的哭声','Weeping on the boat','伊西斯扑在棺木上放声痛哭，哭声大得把国王的小儿子活活吓死了。','Isis threw herself on the coffin and wailed so loudly that the younger son of the king died of it.','claim.v0320.plutarch_osiris.09','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','王子的结局普鲁塔克列出了几种说法，本站只按顺序转述，不判断哪一种更早。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.10','storyver.egyptian.plutarch_ch12_20',10,'被撕成十四块','Torn into fourteen pieces','伊西斯去布托看望在那里长大的儿子荷鲁斯，把装着丈夫遗体的箱子藏在偏僻的地方。','Isis went to her son Horus, who was being reared at Buto, and put the chest out of the way.','claim.v0320.plutarch_osiris.10','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','普鲁塔克记下了“每处举行葬礼”和“分发假像”两种解释，本站两说并存。','2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.11','storyver.egyptian.plutarch_ch12_20',11,'荷鲁斯的战争','The war of Horus','后来，奥西里斯从冥界回到人间，亲自训练儿子荷鲁斯作战。','Later Osiris came from the other world to Horus and trained him for battle.','claim.v0320.plutarch_osiris.11','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.egyptian_plutarch_ch12_20.12','storyver.egyptian.plutarch_ch12_20',12,'被释放的提丰','Typhon released','被锁住的提丰交到了伊西斯手里，她却没有处死他，而是把他放了。','Typhon was handed over to Isis in chains, but she did not put him to death; she let him go.','claim.v0320.plutarch_osiris.12','event.egyptian.osiris_murder_restoration',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','普鲁塔克明说自己略去了最可憎的情节，本站不从其他资料补写；菲莱附近“阿巴顿”岛的描述是他引述的传说。','2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.1','storyver.japanese.kojiki_sect11_19',1,'三位尊贵的孩子','Three illustrious children','伊邪那岐从黄泉回来，在河里洗去污秽。','Returning from Yomi, Izanagi washed away its pollution in a river.','claim.v0320.kojiki_iwato_orochi.01','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.2','storyver.japanese.kojiki_sect11_19',2,'哭干了青山的神','The god who wept the mountains dry','须佐之男不肯去治理大海。','Susanoo would not rule the sea.','claim.v0320.kojiki_iwato_orochi.02','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.3','storyver.japanese.kojiki_sect11_19',3,'披甲的姐姐','The sister in armour','须佐之男说：那么我先去向姐姐天照大神告别，然后再走。','Susanoo said he would first take leave of his elder sister Amaterasu.','claim.v0320.kojiki_iwato_orochi.03','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.4','storyver.japanese.kojiki_sect11_19',4,'天安河边的誓约','The oath by the Tranquil River','须佐之男说：我没有坏心。','Susanoo replied that he had no evil intent: his father had expelled him and he had only come to say farewell.','claim.v0320.kojiki_iwato_orochi.04','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.5','storyver.japanese.kojiki_sect11_19',5,'谁赢了誓约','Who won the oath','天照大神宣布：后来生的五位男神，是从我的东西里生出来的，所以是我的孩子；先生的三位女神，是从你的东西里生出来的，所以是你的孩子。','Amaterasu declared that the five male deities, born from her jewels, were her children, and the three goddesses, born from his sabre, were his.','claim.v0320.kojiki_iwato_orochi.05','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','括号里关于皇室祖先与宗像三女神的说明见于《古事记》的同一段落及后文，属于文本自身的谱系说明。','2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.6','storyver.japanese.kojiki_sect11_19',6,'高天原的胡闹','Riot in the Plain of High Heaven','仗着这场“胜利”，须佐之男在高天原胡作非为。','On the strength of his victory Susanoo ran riot.','claim.v0320.kojiki_iwato_orochi.06','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.7','storyver.japanese.kojiki_sect11_19',7,'天地陷入长夜','The world falls into night','天照大神看见这一切，感到害怕，就打开天之岩户——天上的岩石屋子的门——走了进去，把门牢牢关上，隐居起来。','Terrified at the sight, Amaterasu opened the door of the Heavenly Rock-Dwelling, went in, made it fast and hid herself.','claim.v0320.kojiki_iwato_orochi.07','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.8','storyver.japanese.kojiki_sect11_19',8,'河滩上的众神大会','The assembly in the river-bed','八百万位神聚集在天安河的河滩上开会商议，请高御产巢日神的儿子思金神想办法。','The eight hundred myriad deities assembled in a divine assembly in the bed of the Tranquil River of Heaven and bade Omoikane, child of Takami-musubi, think of a plan.','claim.v0320.kojiki_iwato_orochi.08','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.9','storyver.japanese.kojiki_sect11_19',9,'挂满宝物的杨桐树','The sakaki tree hung with treasures','众神把天香山上一棵长满枝叶的真杨桐树连根拔起，在上面的枝条上挂起那串五百颗勾玉，在中间的枝条上挂起那面八咫镜，在下面的枝条上挂起白色和青色的布帛。','They uprooted a five-hundred-branched true sakaki tree from Mount Kagu of Heaven.','claim.v0320.kojiki_iwato_orochi.09','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.10','storyver.japanese.kojiki_sect11_19',10,'天宇受卖命的舞蹈','The dance of Ame-no-Uzume','天宇受卖命用天香山的日影蔓束起衣袖，用真拆葛做成头饰，手里握着一束天香山的竹叶，在天之岩户前倒扣一只木桶，在上面用力踏脚，踏得咚咚作响。','Ame-no-Uzume bound up her sleeves with heavenly clubmoss from Mount Kagu, made a head-dress of spindle-tree, took in her hand a bundle of bamboo grass from Mount Kagu, and laid an upturned tub before the door of the Heavenly Rock-Dwelling, stamping on it until it resounded.','claim.v0320.kojiki_iwato_orochi.10','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.11','storyver.japanese.kojiki_sect11_19',11,'门缝里的光','Light through the door','天照大神觉得奇怪，把岩户的门稍稍打开一条缝，在里面问：我藏了起来，以为高天原会一片黑暗，苇原中国也会一片黑暗，为什么天宇受卖命还在跳舞，八百万位神都在大笑？','Amaterasu, wondering, opened the door a crack and asked why, when she had thought Heaven and the Central Land would be dark, Ame-no-Uzume danced and all the deities laughed.','claim.v0320.kojiki_iwato_orochi.11','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.12','storyver.japanese.kojiki_sect11_19',12,'放逐与五谷的起源','Expulsion and the origin of grain','八百万位神一起商议，罚须佐之男交出一千桌赎罪的供品，剪掉他的胡子，拔掉他手指和脚趾的指甲，把他赶出了高天原。','The eight hundred myriad deities took counsel together, fined Susanoo a thousand tables of offerings, cut off his beard and pulled out his finger- and toe-nails, and drove him out with a divine expulsion.','claim.v0320.kojiki_iwato_orochi.12','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','《日本书纪》里杀死食物女神的是月读，对象叫保食神；本篇只讲《古事记》的版本。','2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.13','storyver.japanese.kojiki_sect11_19',13,'河上漂来的筷子','Chopsticks on the river','须佐之男被赶出天界，降落到出云国肥河上游一个叫鸟发的地方。','Expelled, Susanoo descended to Torikami at the head of the river Hi in Izumo.','claim.v0320.kojiki_iwato_orochi.13','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.14','storyver.japanese.kojiki_sect11_19',14,'八坛烈酒与草薙剑','Eight vats of liquor and the Kusanagi sword','须佐之男说：我是天照大神的弟弟，刚从天上下来。','Susanoo revealed that he was the elder brother of Amaterasu, just descended from Heaven, and asked for the maiden; the old couple respectfully agreed.','claim.v0320.kojiki_iwato_orochi.14','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“草薙”这个名字在《古事记》的这一段只作注明；名称由来的故事（日本武尊割草）在后文另有讲述。','2026-10-11T01:00:00Z'),
('storyevent.v0320.japanese_kojiki_sect11_19.15','storyver.japanese.kojiki_sect11_19',15,'须贺的宫殿与八云之歌','The palace of Suga and the song of eight clouds','之后，须佐之男在出云国寻找建造宫殿的地方。','Then Susanoo looked for a place in Izumo to build a palace.','claim.v0320.kojiki_iwato_orochi.15','event.japanese.ame_no_iwato',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“日本最早的和歌”是后世（如《古今和歌集》序）的说法，不是《古事记》本文的断言。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.1','storyver.hindu.ramayana_griffith_1_6',1,'一声哀鸣变成了诗','A cry of grief becomes a verse','史诗从诗人自己讲起。','The epic begins with its own poet.','claim.v0320.ramayana_griffith.01','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.2','storyver.hindu.ramayana_griffith_1_6',2,'从祭火里捧出的金碗','The golden bowl from the sacrificial fire','阿逾陀城的国王十车王富有、公正、受人爱戴，却没有儿子。','Daśaratha, king of Ayodhyā, was rich, just and beloved, but had no son.','claim.v0320.ramayana_griffith.02','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.3','storyver.hindu.ramayana_griffith_1_6',3,'跟着仙人进森林','Into the forest with the sage','王子们长大了，个个精通经典和武艺，其中罗摩最受众人喜爱，罗什曼那则像影子一样跟着他。','The princes grew up learned in scripture and arms; Rāma was loved by all, and Lakṣmaṇa followed him like his shadow.','claim.v0320.ramayana_griffith.03','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.4','storyver.hindu.ramayana_griffith_1_6',4,'湿婆的大弓','The bow of Śiva','众友又带着两位王子前往弥提罗国。','Viśvāmitra then led the princes to Mithilā.','claim.v0320.ramayana_griffith.04','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.5','storyver.hindu.ramayana_griffith_1_6',5,'驼背侍女的计谋','The hunchbacked maid''s plot','许多年过去了，十车王年事已高，决定立罗摩为太子，满城百姓欢天喜地，挂起彩旗，准备第二天的灌顶典礼。','Years later the aged Daśaratha resolved to make Rāma heir, and the city hung out banners for the consecration.','claim.v0320.ramayana_griffith.05','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.6','storyver.hindu.ramayana_griffith_1_6',6,'穿上树皮衣','Putting on bark garments','第二天一早，罗摩被召进宫，吉迦伊把国王的决定告诉了他。','Next morning Rāma was summoned and Kaikeyī told him the king''s decision.','claim.v0320.ramayana_griffith.06','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.7','storyver.hindu.ramayana_griffith_1_6',7,'国王之死','The death of the king','车夫苏曼多罗独自赶着空车回来，十车王听说儿子真的走进了森林，悲痛得一病不起。','When the charioteer Sumantra came back alone, Daśaratha, hearing that his son had truly entered the forest, fell ill with grief.','claim.v0320.ramayana_griffith.07','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','那位少年苦行者在后世传统中常被叫做“室罗波那”（Śravaṇa），蚁垤本里没有给出这个名字。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.8','storyver.hindu.ramayana_griffith_1_6',8,'王座上的一双鞋','A pair of sandals on the throne','婆罗多从舅父家回来，才知道父亲已死、兄长被流放，而这一切都是母亲为他谋来的。','Bharata returned from his uncle''s house to learn that his father was dead and his brother exiled, all for his sake.','claim.v0320.ramayana_griffith.08','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.9','storyver.hindu.ramayana_griffith_1_6',9,'首哩薄那迦','Śūrpaṇakhā','罗摩一行在弹宅迦林中住了许多年，保护林中的苦行者，仙人投山把毗湿奴的神弓和永不空竭的箭囊送给了他。','For years they lived in the Daṇḍaka forest protecting its hermits, and the sage Agastya gave Rāma the bow of Vishnu and inexhaustible quivers.','claim.v0320.ramayana_griffith.09','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.10','storyver.hindu.ramayana_griffith_1_6',10,'金色的鹿','The golden deer','首哩薄那迦逃到楞伽，当众责骂罗波那只顾享乐，连自己的国土都保不住，又极力夸赞悉多的美貌。','Śūrpaṇakhā fled to Laṅkā, rebuked Rāvaṇa for his idleness and praised Sītā''s beauty.','claim.v0320.ramayana_griffith.10','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.11','storyver.hindu.ramayana_griffith_1_6',11,'十首魔王与神鹫','The ten-headed king and the vulture','罗什曼那刚走，罗波那就扮成一个云游的婆罗门苦行者来到草屋前。','As soon as Lakṣmaṇa had gone, Rāvaṇa came to the hut disguised as a wandering brahmin ascetic.','claim.v0320.ramayana_griffith.11','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.12','storyver.hindu.ramayana_griffith_1_6',12,'空荡荡的草屋','The empty hut','罗摩在回来的路上遇见了罗什曼那，心中顿生不祥之感。','On the way back Rāma met Lakṣmaṇa and felt dread; the hut was empty.','claim.v0320.ramayana_griffith.12','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.13','storyver.hindu.ramayana_griffith_1_6',13,'猴王的盟约','The pact with the monkey-king','哈奴曼扮成苦行者来迎接他们，把他们带到须羯哩婆面前。','Hanumān, disguised as an ascetic, met them and brought them to Sugrīva, and Rāma and Sugrīva swore friendship around a fire.','claim.v0320.ramayana_griffith.13','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','罗摩从暗处射杀波林是否合乎正法，在印度传统内部本身就有长久的争论；本站只讲蚁垤本里双方的说法。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.14','storyver.hindu.ramayana_griffith_1_6',14,'跨海一跃','The leap across the sea','南路的猴军由安伽陀和哈奴曼率领，找了一个多月仍无消息，来到南方大海边时都绝望了，打算绝食而死。','The southern party under Aṅgada and Hanumān searched for over a month in vain and, reaching the southern sea, despaired and resolved to starve.','claim.v0320.ramayana_griffith.14','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.15','storyver.hindu.ramayana_griffith_1_6',15,'无忧树林中的悉多','Sītā in the aśoka grove','哈奴曼把身体缩得像猫一样小，趁着夜色潜入楞伽。','Shrinking to the size of a cat, Hanumān slipped into Laṅkā by night.','claim.v0320.ramayana_griffith.15','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.16','storyver.hindu.ramayana_griffith_1_6',16,'火烧楞伽','Laṅkā in flames','哈奴曼想试一试罗刹的力量，就把无忧树林毁了个干净，打死了前来捉他的大批卫兵，连罗波那的儿子阿刹也死在他手里。','To test the rākṣasas'' strength Hanumān wrecked the aśoka grove and slew the guards sent against him, among them Rāvaṇa''s son Akṣa.','claim.v0320.ramayana_griffith.16','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.17','storyver.hindu.ramayana_griffith_1_6',17,'海上的石桥','The bridge across the sea','猴军浩浩荡荡向南进发，来到大海边。','The army marched south to the sea.','claim.v0320.ramayana_griffith.17','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.18','storyver.hindu.ramayana_griffith_1_6',18,'楞伽城下的大战','War before Laṅkā','大战开始了。','The war began.','claim.v0320.ramayana_griffith.18','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','哈奴曼取药山的情节在通行本里出现过两次（一次救全军，一次救罗什曼那），各本次序不尽相同；本节只概述其中一次。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.19','storyver.hindu.ramayana_griffith_1_6',19,'罗摩与罗波那','Rāma and Rāvaṇa','儿子和兄弟都死了，罗波那终于亲自出战。','With his sons and brother dead, Rāvaṇa came out to fight himself.','claim.v0320.ramayana_griffith.19','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-11T01:00:00Z'),
('storyevent.v0320.hindu_ramayana_griffith_1_6.20','storyver.hindu.ramayana_griffith_1_6',20,'火的考验与回家','The ordeal of fire and the return home','悉多沐浴更衣后被带到罗摩面前。','Sītā, bathed and adorned, was brought before Rāma.','claim.v0320.ramayana_griffith.20','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','火的考验是今天印度内外讨论最多的情节之一；第七卷（后篇）里还有悉多被第二次放逐的故事，不在本篇范围。','2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.1','storyver.greek.demeter_hymn2_long',1,'尼萨平原的水仙花','A narcissus on the Nysian plain','颂歌从秀发美丽的得墨忒耳唱起，也唱她纤足的女儿珀耳塞福涅——宙斯把她许给了哈得斯。','The hymn begins with rich-haired Demeter and her trim-ankled daughter, whom Zeus gave to Hades.','claim.v0320.demeter_long.01','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.2','storyver.greek.demeter_hymn2_long',2,'无人回应的呼喊','A cry that no one answered','珀耳塞福涅高声呼喊，向至高无上的父亲宙斯求救。','She cried out to her father Zeus, but neither god nor mortal heard her, nor even the olive trees — only tender-hearted Hecate in her cave, and the lord Helios, Hyperion''s bright son.','claim.v0320.demeter_long.02','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.3','storyver.greek.demeter_hymn2_long',3,'九天的火炬','Nine days with torches','剧痛刺穿了得墨忒耳的心。','Bitter pain seized Demeter''s heart.','claim.v0320.demeter_long.03','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.4','storyver.greek.demeter_hymn2_long',4,'太阳看见了一切','The Sun saw everything','第十天黎明时，赫卡忒手持火炬迎面走来，对她说：女王得墨忒耳，四季的带来者，是哪位天神或凡人抢走了珀耳塞福涅，让你如此悲伤？','At dawn on the tenth day Hecate met her with a torch and asked who had taken Persephone, for she had heard but not seen.','claim.v0320.demeter_long.04','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.5','storyver.greek.demeter_hymn2_long',5,'厄琉息斯井边的老妇','An old woman at the well of Eleusis','更加深重、更加狂暴的悲痛涌上得墨忒耳的心头。','Grief yet more terrible came upon Demeter.','claim.v0320.demeter_long.05','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.6','storyver.greek.demeter_hymn2_long',6,'伊阿姆贝的玩笑','Iambe''s jests','女神跨进门槛时，她的头碰到了屋顶的横梁，门口充满了神圣的光辉。','As the goddess crossed the threshold her head touched the roof-beam and the doorway filled with divine radiance.','claim.v0320.demeter_long.06','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.7','storyver.greek.demeter_hymn2_long',7,'火中的婴儿','The child in the fire','女神接受了照顾德摩丰的托付，把孩子抱在她芳香的怀里。','The goddess took Demophoon to her fragrant bosom, and he grew like a god, eating no bread and sucking no milk: by day she anointed him with ambrosia and breathed sweetly on him, and by night, unknown to his parents, she hid him in the heart of the fire like a brand.','claim.v0320.demeter_long.07','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.8','storyver.greek.demeter_hymn2_long',8,'女神现出真身','The goddess reveals herself','头戴华冠的得墨忒耳听见了，勃然大怒，把那可爱的孩子从火中抱出来放在地上，对墨塔涅拉说：愚蠢的凡人啊，你们既看不到将要到来的好运，也看不到灾祸！','Angered, Demeter drew the child from the fire and set him on the ground.','claim.v0320.demeter_long.08','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.9','storyver.greek.demeter_hymn2_long',9,'神庙与可怕的饥荒','The temple and the terrible famine','第二天清晨，刻琉斯召集人民，命令他们为秀发美丽的得墨忒耳在山坡上修建一座富丽的神庙和祭坛，人民立刻照办，神庙很快在女神的意愿下建成。','Celeus called his people and bade them build a rich temple and altar for Demeter, and it rose quickly.','claim.v0320.demeter_long.09','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.10','storyver.greek.demeter_hymn2_long',10,'众神轮番劝说','The gods plead one after another','宙斯先派金翅的伊里斯去召唤秀发美丽的得墨忒耳。','Zeus first sent golden-winged Iris to call Demeter back; finding her in her dark robes in the temple, Iris gave the father''s message, but Demeter was unmoved.','claim.v0320.demeter_long.10','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.11','storyver.greek.demeter_hymn2_long',11,'赫尔墨斯与石榴籽','Hermes and the pomegranate seed','宙斯听了，便派手持金杖的赫尔墨斯前往厄瑞玻斯，用温和的话劝说哈得斯，让他把圣洁的珀耳塞福涅从昏暗中带回光明，与母亲相见。','Zeus sent Hermes of the golden wand down to Erebus to persuade Hades to let Persephone return to the light.','claim.v0320.demeter_long.11','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.12','storyver.greek.demeter_hymn2_long',12,'母女重逢','Mother and daughter','得墨忒耳一看见女儿，就像山林中的狂女一样冲了过去；珀耳塞福涅也跳下马车，奔向母亲，扑进她的怀里。','Seeing her daughter, Demeter rushed forth like a maenad on a wooded mountain, and Persephone leapt down to run to her.','claim.v0320.demeter_long.12','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.13','storyver.greek.demeter_hymn2_long',13,'瑞亚带来宙斯的约定','Rhea brings Zeus''s promise','珀耳塞福涅把一切原原本本地告诉了母亲：她和大洋神的女儿们、帕拉斯和阿耳忒弥斯一起在草地上采花，伸手去摘那朵水仙，大地裂开，冥王把她抢走；赫尔墨斯来接她时，冥王硬是塞给她一颗石榴籽，逼她吃下。','Persephone told her mother everything: the flowers, the narcissus, the opening earth, and how Hades forced the pomegranate seed on her.','claim.v0320.demeter_long.13','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.greek_demeter_hymn2_long.14','storyver.greek.demeter_hymn2_long',14,'麦穗重生与秘仪','The grain returns, and the Mysteries','头戴华冠的得墨忒耳没有违抗。','Demeter did not disobey.','claim.v0320.demeter_long.14','event.greek.persephone_abduction',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','颂歌明言秘仪内容不可说出；本站只讲颂歌公开写下的部分，不重构秘仪内部。','2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.1','storyver.norse.baldr_gylf_long',1,'不祥的梦','Ominous dreams','奥丁的儿子巴德尔是众神中最好的一位，人人都称赞他。','Baldr, Odin''s son, is the best of the gods and all praise him; so fair and bright that the whitest flower is called Baldr''s brow.','claim.v0320.baldr_long.01','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.2','storyver.norse.baldr_gylf_long',2,'万物的誓言','The oaths of all things','于是弗丽嘉出发，让世间万物都立下誓言，不伤害巴德尔：火与水、铁和各种金属、石头、泥土、树木、疾病、走兽、飞鸟、毒物和蛇，全都发了誓。','Frigg took oaths that they would not harm Baldr from fire and water, iron and every metal, stones, the earth, trees, sicknesses, beasts, birds, poison and snakes.','claim.v0320.baldr_long.02','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.3','storyver.norse.baldr_gylf_long',3,'槲寄生','The mistletoe','劳菲之子洛基看见这一切，心里很不高兴，因为巴德尔毫发无伤。','Loki Laufeyjarson was displeased that Baldr took no harm.','claim.v0320.baldr_long.03','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.4','storyver.norse.baldr_gylf_long',4,'盲眼的霍德尔','Blind Höðr','霍德尔站在人圈的外面，因为他是瞎子。','Höðr stood at the edge of the ring, for he was blind.','claim.v0320.baldr_long.04','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.5','storyver.norse.baldr_gylf_long',5,'说不出话的众神','The speechless gods','巴德尔倒下的时候，阿萨众神都说不出话来，双手也失去了力气，不能把他扶起。','When Baldr fell, the Æsir were struck dumb and their hands failed them to lift him.','claim.v0320.baldr_long.05','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.6','storyver.norse.baldr_gylf_long',6,'谁愿意去冥界','Who will ride to Hel?','众神稍稍平静之后，弗丽嘉开口问道：阿萨神族中有谁愿意赢得我全部的爱与恩宠，骑马走上通往冥界的路，去找赫尔，问她要多少赎金才肯让巴德尔回到阿斯加德？','When the gods came to themselves, Frigg asked who among the Æsir would win all her love and favour by riding the road to Hel to find Baldr and offer Hel a ransom to let him come home to Ásgarðr.','claim.v0320.baldr_long.06','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.7','storyver.norse.baldr_gylf_long',7,'灵钟号与火葬','Hringhorni and the pyre','阿萨众神抬起巴德尔的尸体，送到海边。','The Æsir carried Baldr''s body to the sea.','claim.v0320.baldr_long.07','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.8','storyver.norse.baldr_gylf_long',8,'九夜的骑行','Nine nights'' ride','赫尔莫德骑着马走了九天九夜，穿过幽深黑暗的山谷，什么也看不见，直到来到冥河耶尔河边，骑上了铺着闪亮黄金的耶尔桥。','For nine nights Hermóðr rode through dark, deep valleys where he could see nothing, until he came to the river Gjöll and rode onto the Gjallarbrú, roofed with gleaming gold.','claim.v0320.baldr_long.08','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.9','storyver.norse.baldr_gylf_long',9,'赫尔的条件','Hel''s condition','赫尔莫德一路骑到冥界的大门前，他跳下马，把马肚带勒紧，重新上马，用马刺一踢，骏马高高跃起，从大门上方越了过去，一点也没碰到。','At Hel''s gate Hermóðr dismounted, tightened the girth, remounted and spurred Sleipnir, who leapt clean over the gate.','claim.v0320.baldr_long.09','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.10','storyver.norse.baldr_gylf_long',10,'万物都在哭泣','All things weep','赫尔莫德骑马回到阿斯加德，把他的所见所闻原原本本地告诉了众神。','Hermóðr rode back and told all he had seen and heard.','claim.v0320.baldr_long.10','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.11','storyver.norse.baldr_gylf_long',11,'不肯流泪的女巨人','The giantess who would not weep','使者们完成了使命，正在回家的路上，看见一个山洞里坐着一个女巨人，她自称叫作索克。','As the messengers were returning, having done their errand well, they found a giantess sitting in a cave who called herself Þökk.','claim.v0320.baldr_long.11','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','斯诺里说“人们认为”索克就是洛基，这是传统中的认定，不是故事中直接揭穿的情节。','2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.12','storyver.norse.baldr_gylf_long',12,'鲑鱼与网','The salmon and the net','众神对洛基怒不可遏，洛基逃到一座山上，盖了一间有四扇门的房子，好向四面八方都能看见。','The gods were so angry that Loki fled and built a house with four doors on a mountain so he could watch every way, and by day he often hid as a salmon in the Fránangr falls.','claim.v0320.baldr_long.12','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.norse_baldr_gylf_long.13','storyver.norse.baldr_gylf_long',13,'洛基的惩罚','The punishment of Loki','众神把洛基带进一个山洞，竖起三块扁石，在每块石头上钻一个洞。','The gods took Loki into a cave, set up three slabs on edge and bored a hole in each.','claim.v0320.baldr_long.13','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.1','storyver.babylonian.enuma_elish_long',1,'天地还没有名字的时候','When on high the heaven had not been named','当上面的天空还没有名字，下面的大地还没有被叫出名字的时候，只有生育众神的阿普苏——甜水，和生下一切的提亚马特——咸水，把他们的水混合在一起。','When on high the heaven had not been named and below the earth had not been called by name, there was only Apsû, the begetter, and Tiamat, who bore them all, mingling their waters.','claim.v0320.enuma_elish_long.01','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.2','storyver.babylonian.enuma_elish_long',2,'吵闹的众神','The noisy gods','年轻的神们聚在一起，来回嬉闹，搅动了提亚马特的腹部，他们的喧哗让她不得安宁。','The young gods banded together and churned back and forth, disturbing Tiamat''s belly with their din.','claim.v0320.enuma_elish_long.02','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.3','storyver.babylonian.enuma_elish_long',3,'埃阿的咒语','Ea''s spell','众神听说了这个计划，惊慌失措，四处乱跑，然后陷入沉默。','When the gods heard the plan they ran about in panic and then fell silent.','claim.v0320.enuma_elish_long.03','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.4','storyver.babylonian.enuma_elish_long',4,'马尔杜克诞生','The birth of Marduk','就在那座命运之屋、众神之殿里，最能干、最睿智的神诞生了——他就是马尔杜克。','In the chamber of destinies, the shrine of designs, Marduk was born, most able and wisest of gods.','claim.v0320.enuma_elish_long.04','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.5','storyver.babylonian.enuma_elish_long',5,'提亚马特的大军','Tiamat''s host','被风搅得不得安宁的众神来到提亚马特面前，责怪她说：当他们杀死你的丈夫阿普苏时，你袖手旁观；现在安努又造出四方的风，搅乱你的腹部，让我们也睡不着觉。','The gods troubled by the winds reproached Tiamat: when Apsû was slain she did nothing, and now Anu''s winds churn her belly and they cannot sleep.','claim.v0320.enuma_elish_long.05','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.6','storyver.babylonian.enuma_elish_long',6,'没有神敢应战','No god dares to face her','埃阿听说提亚马特的部署，惊得说不出话来，过了很久才平静下来，去向祖父安沙尔报告。','Ea, hearing Tiamat''s plans, was struck dumb, then went to his grandfather Anshar, who beat his thigh and bit his lip in anxiety.','claim.v0320.enuma_elish_long.06','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.7','storyver.babylonian.enuma_elish_long',7,'众神的宴会','The banquet of the gods','安沙尔把他的使者卡卡叫来，派他去找拉赫穆和拉哈穆，把提亚马特的种种部署、众神的恐惧和马尔杜克的条件原原本本地重复一遍，请众神都来集会，为马尔杜克决定命运。','Anshar sent his messenger Kakka to Lahmu and Lahamu to repeat all Tiamat''s preparations, the gods'' fear and Marduk''s condition, and to summon the gods to decree Marduk''s destiny.','claim.v0320.enuma_elish_long.07','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.8','storyver.babylonian.enuma_elish_long',8,'一件衣服的考验','The test of the garment','众神为马尔杜克设立了一座王者的宝座，他坐在父辈们面前，接受统治的权力。','The gods set up a princely dais for Marduk, and he sat before his fathers to receive kingship.','claim.v0320.enuma_elish_long.08','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.9','storyver.babylonian.enuma_elish_long',9,'弓、网与风暴战车','Bow, net and storm chariot','马尔杜克做好了出征的准备：他造了一张弓，把它作为自己的武器，搭上箭，系紧弓弦；他右手拿起权杖，把弓和箭袋挂在身侧。','Marduk made a bow and appointed it his weapon, set the arrow and fitted the string; he took the mace in his right hand and hung bow and quiver at his side.','claim.v0320.enuma_elish_long.09','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.10','storyver.babylonian.enuma_elish_long',10,'决战','The duel','马尔杜克径直走向提亚马特，注视着金古的计谋。','Marduk went straight towards Tiamat and watched for Qingu''s scheme.','claim.v0320.enuma_elish_long.10','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.11','storyver.babylonian.enuma_elish_long',11,'俘虏与命运泥板','The captives and the Tablet of Destinies','提亚马特一死，跟随她的众神四散奔逃，想要保住性命，可是他们被团团围住，无处可逃。','When Tiamat was slain, the gods who marched with her broke ranks and fled to save their lives, but they were surrounded with no escape.','claim.v0320.enuma_elish_long.11','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.12','storyver.babylonian.enuma_elish_long',12,'把身体分成天与地','Heaven and earth from her body','马尔杜克回到提亚马特的身边，用无情的权杖砸碎了她的头骨，割断她的血管，让北风把她的血吹到隐秘的地方。','Marduk returned to Tiamat, crushed her skull with his mace, cut her arteries and let the north wind carry her blood away.','claim.v0320.enuma_elish_long.12','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','第五块泥板长期残缺，后来出土的抄本补足了部分诗行；本站按 eBL 综合文本概述。','2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.13','storyver.babylonian.enuma_elish_long',13,'用金古的血造人','Humankind from Qingu''s blood','众神请马尔杜克决定他们的劳役。','The gods asked Marduk to decide their toil.','claim.v0320.enuma_elish_long.13','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.babylonian_enuma_elish_long.14','storyver.babylonian.enuma_elish_long',14,'巴比伦与五十个名字','Babylon and the fifty names','被解放的阿努纳众神对马尔杜克说：我们要为你建一座圣所，作为你的居所，让我们在其中安歇。','The freed Anunnaki offered to build Marduk a shrine where they too might rest.','claim.v0320.enuma_elish_long.14','event.babylonian.marduk_tiamat',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.1','storyver.sumerian.inanna_etcsl_long',1,'从大天到大地','From the great above to the great below','从伟大的天上，她把心思转向了伟大的地下。','From the great heaven she set her mind on the great below.','claim.v0320.inanna_long.01','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.2','storyver.sumerian.inanna_etcsl_long',2,'七件神力','Seven divine powers','伊南娜取下七种神力，把它们收集在手中，放在手边。','Inana gathered the seven divine powers and held them in her hand.','claim.v0320.inanna_long.02','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.3','storyver.sumerian.inanna_etcsl_long',3,'吩咐宁舒布尔','Instructions to Ninšubur','伊南娜一边走，一边对她的大臣宁舒布尔说：我忠实的大臣，说话可靠的使者，我现在要下到冥界去。','As Inana went, she told her minister Ninšubur: my faithful minister, I am going down to the netherworld.','claim.v0320.inanna_long.03','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.4','storyver.sumerian.inanna_etcsl_long',4,'冥界之门','At the gate of the netherworld','伊南娜来到冥界的宫殿“甘泽尔”前，用力推门，在门口大声喊道：守门人，开门！','At the palace Ganzer Inana pushed aggressively on the door and shouted: open up, doorman!','claim.v0320.inanna_long.04','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.5','storyver.sumerian.inanna_etcsl_long',5,'七道门','Seven gates','内提照吩咐闩上了七道门，又把宫殿的门打开一条缝，对伊南娜说：来吧，伊南娜，进来吧。','Neti bolted the seven gates and opened the palace door a crack: come, Inana, enter.','claim.v0320.inanna_long.05','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.6','storyver.sumerian.inanna_etcsl_long',6,'冥后的注视','The look of death','伊南娜弯着腰、赤身裸体地走了进去。','After she had crouched down and her clothes had been removed, they were carried away.','claim.v0320.inanna_long.06','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.7','storyver.sumerian.inanna_etcsl_long',7,'三天三夜','Three days and three nights','三天三夜过去了，伊南娜没有回来，她的大臣宁舒布尔照女主人的吩咐，在废墟中为她哀哭，在议会厅里为她敲鼓，在众神的家中奔走，抓伤自己的眼睛、嘴和大腿，像穷人一样只穿一件衣服。','After three days and three nights had passed, Ninšubur did as her mistress had ordered: she lamented in the ruins, beat the drum in the assembly, went round the gods'' houses, lacerated her eyes, mouth and thighs and dressed like a pauper.','claim.v0320.inanna_long.07','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.8','storyver.sumerian.inanna_etcsl_long',8,'恩基指甲里的泥','Dirt from Enki''s fingernail','宁舒布尔来到埃利都，在恩基面前哭诉。','Ninšubur went to Eridug and wept before Enki.','claim.v0320.inanna_long.08','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.9','storyver.sumerian.inanna_etcsl_long',9,'复活','Revival','两个小人照恩基的吩咐，像苍蝇一样绕着门飞，像幽灵一样从门轴下溜了进去。','They did as Enki said, slipping in like flies and phantoms.','claim.v0320.inanna_long.09','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.10','storyver.sumerian.inanna_etcsl_long',10,'跟在身后的恶魔','The demons at her side','伊南娜正要从冥界上去，阿努纳众神抓住了她，说：有谁从冥界上去，能够安然无恙？','As Inana was about to ascend, the Anuna seized her: who has ever ascended from the netherworld unscathed?','claim.v0320.inanna_long.10','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.11','storyver.sumerian.inanna_etcsl_long',11,'得到赦免的人','Those who were spared','伊南娜走出冥界，宁舒布尔扑倒在她脚下，身上满是灰尘，穿着肮脏的衣服。','As Inana came out, Ninšubur threw herself at her feet, covered in dust and dressed in a filthy garment.','claim.v0320.inanna_long.11','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-11T01:00:00Z'),
('storyevent.v0320.sumerian_inanna_etcsl_long.12','storyver.sumerian.inanna_etcsl_long',12,'杜木兹','Dumuzid','她们来到库拉巴的大苹果树下，看见伊南娜的丈夫杜木兹穿着华丽的衣服，坐在高高的王座上，没有为她哀悼。','Beneath the great apple tree of Kul-aba they found Dumuzid, Inana''s husband, clothed in a magnificent garment and seated on a magnificent throne, not mourning.','claim.v0320.inanna_long.12','event.sumerian.inanna_descent',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','结尾诗行残缺；杜木兹与盖什提南娜各在冥界半年的安排依据可读出的部分，其他苏美尔作品另有不同讲法。','2026-10-11T01:00:00Z');

